import re, sys, json

def read(p): return open(p).read().split('\n')

long_lines = read('/tmp/help_actual.txt')
short_lines = read('/tmp/help_short.txt')

# parse short help: option name -> help text
short = {}
i = 0
# find Options: section
for idx,l in enumerate(short_lines):
    if l.startswith('Options:'):
        start = idx+1
        break
for l in short_lines[start:]:
    if not l.strip(): continue
    m = re.match(r'^\s+(-[a-zA-Z@], )?(--[a-zA-Z0-9-]+|-\[?[A-Z_0-9]+\]?)', l)
    if not m: continue
    name_part = l.strip().split('  ')[0].strip()
    # get help text: after two+ spaces following the name
    mm = re.match(r'^(\s*)(-\S+|-\S+,\s+\S+)\s{2,}(.*)$', l)
    if mm:
        helptxt = mm.group(3).strip()
    else:
        continue
    short[name_part] = helptxt

# parse long help
opts = []
cur = None
for idx,l in enumerate(long_lines):
    if l.startswith('Options:'):
        start = idx+1
        break
for l in long_lines[start:]:
    m = re.match(r'^\s{2,4}(-[a-zA-Z@],\s+)?(--[a-zA-Z0-9-]+)(\s+<[^>]+>)?\s*$', l)
    if m:
        cur = {'short': (m.group(1) or '').strip().lstrip('-'), 'long': m.group(2), 'value_name': (m.group(3) or '').strip().strip('<>'), 'paras': []}
        opts.append(cur)
        continue
    if cur is not None:
        cur['paras'].append(l)

def clean(paras):
    # strip leading indent (10 spaces)
    out = []
    for l in paras:
        if l.startswith(' '*10):
            out.append(l[10:])
        elif l.strip()=='' :
            out.append('')
        else:
            out.append(l.strip())
    return out

res = []
for o in opts:
    paras = clean(o['paras'])
    # remove trailing default/possible-values entries
    defaults = None
    pv = None
    while paras and (paras[-1].startswith('[default:') or paras[-1].startswith('[possible values:')):
        last = paras.pop()
        if last.startswith('[default:'):
            defaults = last[len('[default: '):-1]
        else:
            pv = last[len('[possible values: '):-1]
    # also 'Possible values:' block for detect-dark-light
    if paras and paras[-1].startswith('Possible values:'):
        paras.pop()
        vals = []
        for p in paras[len(paras)-len(pv.split(', ')):]:
            pass
    res.append({'short': o['short'], 'long': o['long'], 'value_name': o['value_name'], 'paras': paras, 'default': defaults, 'pv': pv})

json.dump(res, open('/tmp/opts.json','w'), indent=1)
print(len(res))
for o in res[:3]: print(o)
PYEOF
python3 /tmp/gen_args.py"}

