import re, json

long_lines = open('/tmp/help_actual.txt').read().split('\n')
short_lines = open('/tmp/help_short.txt').read().split('\n')

# ---- parse short help
short = {}
start = [i for i,l in enumerate(short_lines) if l.startswith('Options:')][0]+1
for l in short_lines[start:]:
    if not l.strip(): continue
    mm = re.match(r'^(\s+)(-\S+, )?(--\S+|-\S+)\s{2,}(.*)$', l)
    if mm:
        short[mm.group(3)] = mm.group(4).strip()

def parse_short_txt(helptxt):
    m = re.search(r'(\s*\[default: .*)$', helptxt)
    return helptxt

# ---- parse long help
opts = []
cur = None
start = [i for i,l in enumerate(long_lines) if l.startswith('Options:')][0]+1
for l in long_lines[start:]:
    m = re.match(r'^ {6}(-\S, )?(--\S+)( <[^>]+>)?$', l)
    if m:
        cur = {'short': (m.group(1) or '').strip().lstrip('-'), 'long': m.group(2),
               'value_name': (m.group(3) or '').strip().strip('<>'), 'raw': []}
        opts.append(cur)
        continue
    if cur is not None:
        cur['raw'].append(l)

def clean(paras):
    out = []
    for l in paras:
        if l.startswith(' '*10): out.append(l[10:])
        elif l.strip()=='': out.append('')
        else: out.append(l.strip())
    return out

res = []
for o in opts:
    paras = clean(o['raw'])
    defaults = None; pv = None; valhelp = None
    while paras and (paras[-1].startswith('[default:') or paras[-1].startswith('[possible values:')):
        last = paras.pop()
        if last.startswith('[default:'): defaults = last[len('[default: '):-1]
        else: pv = last[len('[possible values: '):-1]
    if paras and paras[-1].startswith('Possible values:'):
        # per-value help
        block = []
        paras.pop()
        while paras and paras[-1].startswith('- ') or (paras and paras[-1].startswith('  ')):
            if not paras[-1].startswith('- ') and not paras[-1].startswith('    '): break
            block.append(paras.pop())
        block.reverse()
        valhelp = block
    res.append({'short': o['short'], 'long': o['long'], 'value_name': o['value_name'],
                'paras': paras, 'default': defaults, 'pv': pv, 'valhelp': valhelp,
                'short_help': short.get(o['long'])})

json.dump(res, open('/tmp/opts.json','w'), indent=1)
print("n=", len(res))
