import os, pty, sys, fcntl, termios, struct, re, json
def run(width):
    master, slave = pty.openpty()
    fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack('HHHH', 40, width, 0, 0))
    pid = os.fork()
    if pid == 0:
        os.close(master); os.dup2(slave,0); os.dup2(slave,1); os.dup2(slave,2)
        os.execv('/workspace/executable', ['delta','--help'])
    os.close(slave)
    out=b''
    while True:
        try: d = os.read(master, 65536)
        except OSError: break
        if not d: break
        out += d
    os.waitpid(pid,0); os.close(master)
    txt = re.sub(r'\x1b\[[0-9;]*m','',out.decode('utf8','replace').replace('\r',''))
    lines=[l for l in txt.split('\n') if l.strip()]
    # collect blocks: option header -> following indented lines
    blocks={}
    cur=None
    for l in lines:
        m=re.match(r'^ {2,6}(-\S, )?(--\S+)( <[^>]+>)?$', l)
        if m:
            cur=m.group(2); blocks[cur]=[]
            continue
        if cur is not None:
            if l.startswith('          '): blocks[cur].append(l[10:])
            elif l.startswith('  -'): cur=None
            else:
                cur=None
    return blocks
