//! Style strings: colors and attributes.

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Color {
    /// ANSI color name (0-15)
    Ansi(u8),
    /// ANSI 256-color number (16-255)
    Ansi256(u8),
    Rgb(u8, u8, u8),
    /// Automatically chosen background color (resolved at config time)
    Auto,
    /// Terminal default foreground/background
    Normal,
    /// Syntax-highlighted foreground
    Syntax,
    /// Pass through raw ANSI from the input
    Raw,
}

pub const ATTR_BOLD: u32 = 1;
pub const ATTR_DIM: u32 = 2;
pub const ATTR_ITALIC: u32 = 4;
pub const ATTR_UNDERLINE: u32 = 8;
pub const ATTR_BLINK: u32 = 16;
pub const ATTR_REVERSE: u32 = 32;
pub const ATTR_HIDDEN: u32 = 64;
pub const ATTR_STRIKE: u32 = 128;
pub const ATTR_OVERLINE: u32 = 256;
pub const ATTR_OMIT: u32 = 512;

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Style {
    pub fg: Option<Color>,
    pub bg: Option<Color>,
    pub attrs: u32,
    pub raw: bool,
    pub syntax: bool,
    pub box_: bool,
    pub underline_decoration: bool,
    pub overline_decoration: bool,
    pub file: bool,
    pub line_number: bool,
}

impl Default for Style {
    fn default() -> Self {
        Style {
            fg: None,
            bg: None,
            attrs: 0,
            raw: false,
            syntax: false,
            box_: false,
            underline_decoration: false,
            overline_decoration: false,
            file: false,
            line_number: false,
        }
    }
}

impl Style {
    pub fn is_empty(&self) -> bool {
        self.fg.is_none() && self.bg.is_none() && self.attrs == 0 && !self.syntax && !self.raw
    }
    /// True when the style has a concrete (non-auto) background color.
    pub fn has_bg(&self) -> bool {
        matches!(self.bg, Some(Color::Ansi(_)) | Some(Color::Ansi256(_)) | Some(Color::Rgb(..)))
    }
    pub fn is_omitted(&self) -> bool {
        self.attrs & ATTR_OMIT != 0
    }
    pub fn is_box(&self) -> bool {
        self.box_ || self.underline_decoration || self.overline_decoration
    }
}
