//! Minimal git-config file reader following the rules in git-config(1) FILES.

#[derive(Clone, Debug)]
pub struct Entry {
    pub section: String,
    pub subsection: Option<String>,
    pub key: String,
    pub value: String,
}

#[derive(Clone, Debug, Default)]
pub struct GitConfig {
    pub entries: Vec<Entry>,
}

fn unquote(v: &str) -> String {
    let v = v.trim();
    if v.len() >= 2 && (v.starts_with('"') && v.ends_with('"')) {
        let inner = &v[1..v.len() - 1];
        let mut out = String::new();
        let mut chars = inner.chars();
        while let Some(c) = chars.next() {
            if c == '\\' {
                match chars.next() {
                    Some('n') => out.push('\n'),
                    Some('t') => out.push('\t'),
                    Some('\\') => out.push('\\'),
                    Some('"') => out.push('"'),
                    Some(other) => {
                        out.push('\\');
                        out.push(other);
                    }
                    None => out.push('\\'),
                }
            } else {
                out.push(c);
            }
        }
        out
    } else {
        v.to_string()
    }
}

impl GitConfig {
    pub fn parse(text: &str, base_dir: Option<&std::path::Path>) -> GitConfig {
        let mut cfg = GitConfig::default();
        let mut section: Option<String> = None;
        let mut subsection: Option<String> = None;
        let mut pending_include: Option<String> = None;
        for raw in text.split('\n') {
            let line = raw.trim();
            if line.is_empty() || line.starts_with('#') || line.starts_with(';') {
                continue;
            }
            if line.starts_with('[') {
                let inner = line.trim_start_matches('[').trim_end_matches(']').trim();
                let inner = inner.trim();
                if let Some(idx) = inner.find('"') {
                    let name = inner[..idx].trim().to_lowercase();
                    let sub = inner[idx..].trim().trim_matches('"').to_string();
                    section = Some(name);
                    subsection = Some(sub);
                } else {
                    section = Some(inner.to_lowercase());
                    subsection = None;
                }
                continue;
            }
            if let Some(eq) = line.find('=') {
                let key = line[..eq].trim().to_lowercase();
                let val = unquote(&line[eq + 1..]);
                let sec = section.clone().unwrap_or_default();
                let sub = subsection.clone();
                // git config boolean: bare key means true
                if val.is_empty() && line[eq + 1..].trim().is_empty() {
                    cfg.push_entry(sec, sub, key, "true".to_string(), base_dir);
                } else {
                    cfg.push_entry(sec, sub, key, val, base_dir);
                }
                continue;
            }
            // bare key (implicit true) or include
            let key = line.to_lowercase();
            if section.as_deref() == Some("include") && key == "path" {
                // handled on the next line
                continue;
            }
            let sec = section.clone().unwrap_or_default();
            let sub = subsection.clone();
            cfg.push_entry(sec, sub, key, "true".to_string(), base_dir);
        }
        cfg
    }

    fn push_entry(
        &mut self,
        section: String,
        subsection: Option<String>,
        key: String,
        value: String,
        base_dir: Option<&std::path::Path>,
    ) {
        if section == "include" && key == "path" {
            let path = resolve_include_path(&value, base_dir);
            if let Some(p) = path {
                if let Ok(text) = std::fs::read_to_string(&p) {
                    let inc = GitConfig::parse(&text, p.parent());
                    self.entries.extend(
                        inc.entries
                            .into_iter()
                            .map(|mut e| {
                                if e.section == "delta" {
                                    // keep as-is
                                }
                                e
                            })
                            .collect::<Vec<_>>(),
                    );
                }
            }
            return;
        }
        self.entries.push(Entry {
            section,
            subsection,
            key,
            value,
        });
    }

    /// Return the last value for (section, subsection, key).
    pub fn get(&self, section: &str, subsection: Option<&str>, key: &str) -> Option<&str> {
        self.entries
            .iter()
            .rev()
            .find(|e| {
                e.section == section
                    && e.key == key
                    && match (e.subsection.as_deref(), subsection) {
                        (None, None) => true,
                        (Some(a), Some(b)) => a == b,
                        _ => false,
                    }
            })
            .map(|e| e.value.as_str())
    }

    /// All values for a key, in order of appearance.
    pub fn get_all(&self, section: &str, key: &str) -> Vec<&str> {
        self.entries
            .iter()
            .filter(|e| e.section == section && e.key == key)
            .map(|e| e.value.as_str())
            .collect()
    }

    /// All subsections of `section` in order of appearance.
    pub fn subsections(&self, section: &str) -> Vec<String> {
        let mut out: Vec<String> = Vec::new();
        for e in self.entries.iter() {
            if e.section == section {
                if let Some(s) = &e.subsection {
                    if !out.contains(s) {
                        out.push(s.clone());
                    }
                }
            }
        }
        out
    }
}

fn resolve_include_path(v: &str, base_dir: Option<&std::path::Path>) -> Option<std::path::PathBuf> {
    let v = v.trim();
    let tilde_expanded = if v == "~" {
        home_dir()?
    } else if let Some(rest) = v.strip_prefix("~/") {
        format!("{}/{}", home_dir()?, rest)
    } else {
        v.to_string()
    };
    let p = std::path::PathBuf::from(&tilde_expanded);
    if p.is_absolute() {
        Some(p)
    } else {
        base_dir.map(|b| b.join(p))
    }
}

fn home_dir() -> Option<String> {
    std::env::var("HOME").ok()
}
