//! Configuration resolution: defaults, git config, features, env vars, CLI.

use crate::style::{Color, Style};

pub const VERSION: &str = "0.18.2";

// ---- "auto" background colors used for minus/plus styles -------------------
pub const MINUS_BG_DARK: &str = "#3f0001";
pub const MINUS_EMPH_BG_DARK: &str = "#901011";
pub const PLUS_BG_DARK: &str = "#002800";
pub const PLUS_EMPH_BG_DARK: &str = "#006000";
pub const MINUS_BG_LIGHT: &str = "#ffe0e0";
pub const MINUS_EMPH_BG_LIGHT: &str = "#ffc0c0";
pub const PLUS_BG_LIGHT: &str = "#d0ffd0";
pub const PLUS_EMPH_BG_LIGHT: &str = "#a0efa0";

pub struct RawConfig {
    /// option name (without leading --) -> raw value
    pub map: std::collections::HashMap<String, String>,
}

impl RawConfig {
    pub fn new() -> Self {
        RawConfig {
            map: std::collections::HashMap::new(),
        }
    }
    pub fn set(&mut self, k: &str, v: &str) {
        self.map.insert(k.to_string(), v.to_string());
    }
    pub fn get(&self, k: &str) -> Option<&str> {
