/// The 16 ANSI color names, mapped to codes 0-15.
pub fn ansi_color(name: &str) -> Option<u8> {
    let n = name.to_lowercase();
    let (base, bright) = if let Some(rest) = n.strip_prefix("bright") {
        (rest, true)
    } else {
        (n.as_str(), false)
    };
    let code = match base {
        "black" => 0,
        "red" => 1,
        "green" => 2,
        "yellow" => 3,
        "blue" => 4,
        "magenta" | "purple" => 5,
        "cyan" => 6,
        "white" => 7,
        _ => return None,
    };
    Some(code + if bright { 8 } else { 0 })
}

/// Display name for an ANSI color (matches delta's output).
pub fn ansi_display_name(code: u8) -> &'static str {
    match code {
        0 => "black",
        1 => "red",
        2 => "green",
        3 => "yellow",
        4 => "blue",
        5 => "purple",
        6 => "cyan",
        7 => "white",
        8 => "brightblack",
        9 => "brightred",
        10 => "bright-green",
        11 => "brightyellow",
        12 => "bright-blue",
        13 => "bright-purple",
        14 => "brightcyan",
        15 => "bright-white",
        _ => "",
    }
}

pub fn parse_hex(s: &str) -> Option<(u8, u8, u8)> {
    let s = s.trim().trim_start_matches('#');
    let digits = |n: usize| -> Option<Vec<u8>> {
        if s.len() != n * 2 {
            return None;
        }
        let mut out = Vec::new();
        for i in 0..n {
            out.push(u8::from_str_radix(&s[i * 2..i * 2 + 2], 16).ok()?);
        }
        Some(out)
    };
    match digits(3) {
        Some(v) => Some((v[0], v[1], v[2])),
        None => match digits(1) {
            Some(v) => {
                let r = v[0];
                Some((r, r, r))
            }
            None => match digits(2) {
                Some(v) => {
                    let a = v[0] as f64 / 255.0;
                    let scale = |x: u8| -> u8 { (x as f64 * a).round() as u8 };
                    Some((scale(v[1]), scale(v[2]), scale(v[3])))
                }
                None => None,
            },
        },
    }
}

/// Convert an RGB color to the nearest ANSI 256 color.
pub fn rgb_to_ansi256(r: u8, g: u8, b: u8) -> u8 {
    let levels = [0u32, 95, 135, 175, 215, 255];
    let ri = nearest_level(r as u32);
    let gi = nearest_level(g as u32);
    let bi = nearest_level(b as u32);
    let cube = (16 + 36 * ri + 6 * gi + bi) as u32;
    // gray ramp: 232 + n, value = 8 + 10*n
    if r == g && g == b {
        let v = r as u32;
