    let bi = nearest_level(b as u32);
    let cube = (16 + 36 * ri + 6 * gi + bi) as u32;
    // gray ramp: 232 + n, value = 8 + 10*n
    if r == g && g == b {
        let v = r as u32;
        if v == 0 {
            return 16;
        }
        if v == 255 {
            return 231;
        }
        if v >= 8 && v <= 238 {
            let n = ((v - 8) as f64 / 10.0).round() as u32;
            let n = n.min(23);
            let gray = 232 + n;
            let gray_val = 8 + 10 * n;
            let d_gray = (v as i64 - gray_val as i64).abs() * 3;
            let d_cube = (v as i64 - levels[ri] as i64).abs() * 3;
            if d_gray < d_cube {
                return gray as u8;
            }
            return cube as u8;
        }
        return cube as u8;
    }
    // compare cube candidate with the best gray
    let cube_dist = dist(r, g, b, levels[ri], levels[gi], levels[bi]);
    let best_gray = best_gray_index(r, g, b);
    if let Some((n, gray_val)) = best_gray {
        let gray_dist = dist(r, g, b, gray_val, gray_val, gray_val);
        if gray_dist < cube_dist {
            return (232 + n) as u8;
        }
    }
    cube as u8
}

fn dist(r: u8, g: u8, b: u8, r2: u32, g2: u32, b2: u32) -> u64 {
    let d = |a: u8, x: u32| -> u64 {
        let a = a as i64;
        let x = x as i64;
        let d = (a - x).abs() as u64;
        d * d
    };
    d(r, r2) + d(g, g2) + d(b, b2)
}

fn nearest_level(v: u32) -> u32 {
    let levels = [0u32, 95, 135, 175, 215, 255];
    let mut best = 0u32;
    let mut bestd = i64::MAX;
    for (i, l) in levels.iter().enumerate() {
        let d = (*l as i64 - v as i64).abs();
        if d < bestd {
            bestd = d;
            best = i as u32;
        }
    }
    best
}

fn best_gray_index(r: u8, g: u8, b: u8) -> Option<(u32, u32)> {
    let avg = (r as u32 + g as u32 + b as u32) / 3;
    if avg < 8 || avg > 238 {
        return None;
    }
    let n = ((avg - 8) as f64 / 10.0).round() as u32;
    let n = n.min(23);
    Some((n, 8 + 10 * n))
}
