/// Parse a delta style string. Returns an error message on failure.
pub fn parse_style_string(
    s: &str,
    is_decoration: bool,
    true_color: bool,
) -> Result<Style, String> {
    let mut st = Style::default();
    let mut ncolors = 0;
    for tok in s.split_whitespace() {
        if tok == "raw" {
            if is_decoration {
                return Err("'raw' may not be used in a decoration style.".to_string());
            }
            st.raw = true;
            st.fg = None;
            st.bg = None;
            st.attrs = 0;
            st.syntax = false;
            continue;
        }
        if tok == "syntax" {
            if is_decoration {
                return Err("'syntax' may not be used in a decoration style.".to_string());
            }
            st.fg = Some(Color::Syntax);
            st.syntax = true;
            continue;
        }
        if let Some(sp) = special_attr(tok) {
            match sp {
                SpecialAttr::Box => {
                    if !is_decoration && !allows_box() {
                        return Err(format!("Invalid color or style attribute: {}", tok));
                    }
                    st.box_ = true;
                }
                SpecialAttr::Underline => {
                    st.underline_decoration = true;
                    st.attrs |= ATTR_UNDERLINE;
                }
                SpecialAttr::Overline => {
                    if !is_decoration {
                        return Err(format!("Invalid color or style attribute: {}", tok));
                    }
                    st.overline_decoration = true;
                }
                SpecialAttr::File => st.file = true,
                SpecialAttr::LineNumber => st.line_number = true,
                SpecialAttr::Omit => st.attrs |= ATTR_OMIT,
                SpecialAttr::None_ => {
                    if !is_decoration && !allows_box() {
                        return Err(format!("Invalid color or style attribute: {}", tok));
                    }
                    // 'none' clears the decoration
                    st.box_ = false;
                    st.underline_decoration = false;
                    st.overline_decoration = false;
                }
            }
            continue;
        }
        if let Some(code) = attr_code(tok) {
            st.attrs |= code;
            continue;
        }
        // color
        let color = match parse_color(tok, true_color) {
            Some(c) => c,
            None => return Err(format!("Invalid color or style attribute: {}", tok)),
        };
