];

pub fn parse_color(tok: &str, true_color: bool) -> Option<Color> {
    let t = tok;
    match t {
        "auto" => return Some(Color::Auto),
        "normal" => return Some(Color::Normal),
        "raw" => return Some(Color::Raw),
        "syntax" => return Some(Color::Syntax),
        _ => {}
    }
    if let Some(c) = ansi_color(t) {
        return Some(Color::Ansi(c));
    }
    if let Ok(n) = t.parse::<u32>() {
        if n <= 255 {
            return Some(Color::Ansi256(n as u8));
        }
        return None;
    }
    if t.starts_with('#') {
        let (r, g, b) = parse_hex(t)?;
        return Some(if true_color {
            Color::Rgb(r, g, b)
        } else {
            Color::Ansi256(rgb_to_ansi256(r, g, b))
        });
    }
    if let Some((r, g, b)) = css_color(t) {
        return Some(if true_color {
            Color::Rgb(r, g, b)
        } else {
            Color::Ansi256(rgb_to_ansi256(r, g, b))
        });
    }
    None
}

impl Color {
    /// SGR parameter list for this color as foreground.
    pub fn sgr_fg(&self) -> Option<String> {
        match self {
            Color::Ansi(c) => {
                if *c < 8 {
                    Some(format!("{}", 30 + *c))
                } else {
                    Some(format!("{}", 90 + (*c - 8)))
                }
            }
            Color::Ansi256(n) => Some(format!("38;5;{}", n)),
            Color::Rgb(r, g, b) => Some(format!("38;2;{};{};{}", r, g, b)),
            _ => None,
        }
    }
    /// SGR parameter list for this color as background.
    pub fn sgr_bg(&self) -> Option<String> {
        match self {
            Color::Ansi(c) => {
                if *c < 8 {
                    Some(format!("{}", 40 + *c))
                } else {
                    Some(format!("{}", 100 + (*c - 8)))
                }
            }
            Color::Ansi256(n) => Some(format!("48;5;{}", n)),
            Color::Rgb(r, g, b) => Some(format!("48;2;{};{};{}", r, g, b)),
            _ => None,
        }
    }
    /// Name used when displaying the configuration.
    pub fn display_name(&self) -> String {
        match self {
            Color::Ansi(c) => ansi_display_name(*c).to_string(),
            Color::Ansi256(n) => format!("{}", n),
            Color::Rgb(r, g, b) => format!("#{:02x}{:02x}{:02x}", r, g, b),
            Color::Auto => "normal".to_string(),
            Color::Normal => "normal".to_string(),
            Color::Syntax => "syntax".to_string(),
            Color::Raw => "raw".to_string(),
        }
    }
}

impl Style {
    /// The ANSI escape sequence that starts this style.
    pub fn to_ansi(&self) -> String {
        if self.raw {
            return String::new();
        }
        let mut parts: Vec<String> = Vec::new();
        let mut codes: Vec<String> = Vec::new();
        for c in [ATTR_BOLD, ATTR_DIM, ATTR_ITALIC, ATTR_BLINK, ATTR_REVERSE, ATTR_STRIKE].iter() {
            if self.attrs & *c != 0 {
                codes.push(match *c {
                    ATTR_BOLD => "1".to_string(),
                    ATTR_DIM => "2".to_string(),
                    ATTR_ITALIC => "3".to_string(),
                    ATTR_BLINK => "5".to_string(),
                    ATTR_REVERSE => "7".to_string(),
                    ATTR_STRIKE => "9".to_string(),
                    _ => continue,
                });
            }
        }
        if let Some(bg) = &self.bg {
            if let Some(s) = bg.sgr_bg() {
                codes.push(s);
            }
        }
        if let Some(fg) = &self.fg {
            if let Some(s) = fg.sgr_fg() {
                codes.push(s);
            }
        }
        parts.push(codes.join(";"));
        if codes.is_empty() {
            return String::new();
        }
        format!("\x1b[{}m", codes.join(";"))
    }

    /// Human-readable representation used by --show-config.
    pub fn display(&self) -> String {
        if self.raw {
            return "raw".to_string();
        }
        let mut out: Vec<String> = Vec::new();
        for (flag, name) in [
            (ATTR_BLINK, "blink"),
            (ATTR_BOLD, "bold"),
            (ATTR_DIM, "dim"),
            (ATTR_ITALIC, "italic"),
            (ATTR_REVERSE, "reverse"),
            (ATTR_STRIKE, "strike"),
            (ATTR_OMIT, "omit"),
        ] {
            if self.attrs & flag != 0 {
                out.push(name.to_string());
            }
        }
        match &self.fg {
            Some(c) => out.push(c.display_name()),
            None => out.push("normal".to_string()),
        }
        if let Some(c) = &self.bg {
            if *c != Color::Normal {
                out.push(c.display_name());
            }
        }
        out.join(" ")
    }
}
