/// Highlight a single line: returns (start_char, end_char, token type) spans
/// covering the whole line.
pub fn highlight(lang: &str, line: &str, max_len: usize) -> Vec<(usize, usize, Tok)> {
    let def = lang_def(lang);
    if def.line_comment.is_empty() && def.block_comment.is_none() && def.string_delims.is_empty()
        && def.keywords.is_empty()
    {
        // plain text: single span
        if line.is_empty() {
            return vec![];
        }
        return vec![(0, line.chars().count(), Tok::Plain)];
    }
    let chars: Vec<char> = line.chars().collect();
    let n = chars.len().min(max_len);
    let mut out: Vec<(usize, usize, Tok)> = Vec::new();
    let mut i = 0;
    let mut plain_start = 0;
    let mut push_plain = |out: &mut Vec<(usize, usize, Tok)>, plain_start: &mut usize, end: usize| {
        if *plain_start < end {
            out.push((*plain_start, end, Tok::Plain));
        }
        *plain_start = end;
    };
    while i < n {
        let rest: String = chars[i..].iter().collect();
        // line comments
        let mut matched = false;
        for lc in &def.line_comment {
            if rest.starts_with(lc) {
                push_plain(&mut out, &mut plain_start, i);
                out.push((i, n, Tok::Comment));
                return out;
            }
        }
        if let Some((bs, be)) = def.block_comment {
            if rest.starts_with(bs) {
                push_plain(&mut out, &mut plain_start, i);
                let mut j = i + bs.chars().count();
                let mut end = n;
                while j < n {
                    let r2: String = chars[j..].iter().collect();
                    if r2.starts_with(be) {
                        end = j + be.chars().count();
                        break;
                    }
                    j += 1;
                }
                out.push((i, end.min(n), Tok::Comment));
                i = end.min(n);
                plain_start = i;
                matched = true;
            }
        }
        if !matched {
            for d in &def.string_delims {
                if chars[i] == *d {
                    push_plain(&mut out, &mut plain_start, i);
                    let mut j = i + 1;
                    let mut end = n;
                    while j < n {
                        if chars[j] == '\\' {
                            j += 2;
                            continue;
                        }
                        if chars[j] == *d {
                            end = j + 1;
                            break;
                        }
                        j += 1;
                    }
                    out.push((i.min(n), end.min(n), Tok::String));
                    i = end.min(n);
                    plain_start = i;
                    matched = true;
                    break;
                }
            }
        }
        if !matched && (chars[i].is_alphabetic() || chars[i] == '_') {
            let mut j = i;
            while j < n && (chars[j].is_alphanumeric() || chars[j] == '_' || def.ident_extra.contains(chars[j])) {
                j += 1;
            }
            let word: String = chars[i..j].iter().collect();
            push_plain(&mut out, &mut plain_start, i);
            if def.keywords.contains(&word.as_str()) {
                out.push((i, j, Tok::Keyword));
            } else if j < n && chars[j] == '(' {
                out.push((i, j, Tok::Function));
            } else {
                out.push((i, j, Tok::Plain));
            }
            i = j;
            plain_start = i;
            matched = true;
        }
        if !matched && chars[i].is_ascii_digit() {
            let mut j = i;
            while j < n && (chars[j].is_ascii_digit() || chars[j] == '.' || chars[j] == 'x'
                || chars[j] == 'o' || chars[j] == 'b' || chars[j] == '_'
                || chars[j].is_ascii_hexdigit()) {
                j += 1;
            }
            push_plain(&mut out, &mut plain_start, i);
            out.push((i, j, Tok::Number));
            i = j;
            plain_start = i;
            matched = true;
        }
        if !matched && "+-*/%=<>!&|^~?:;,.(){}[]".contains(chars[i]) {
            push_plain(&mut out, &mut plain_start, i);
            if "+-*/%=<>!&|^~?".contains(chars[i]) {
                out.push((i, i + 1, Tok::Operator));
            } else {
                out.push((i, i + 1, Tok::Plain));
            }
            i += 1;
            plain_start = i;
            matched = true;
        }
        if !matched {
            i += 1;
        }
    }
    push_plain(&mut out, &mut plain_start, n);
    if n < chars.len() {
        out.push((n, chars.len(), Tok::Plain));
    }
    out
}
