                    let r2: String = chars[j..].iter().collect();
                    if r2.starts_with(be) {
                        end = j + be.chars().count();
                        break;
                    }
                    j += 1;
                }
                out.push((i, end.min(n), Tok::Comment));
                i = end.min(n);
                plain_start = i;
                matched = true;
            }
        }
        if !matched {
            for d in &def.string_delims {
                if chars[i] == *d {
                    push_plain(&mut out, &mut plain_start, i);
                    let mut j = i + 1;
                    let mut end = n;
