            let word: String = chars[i..j].iter().collect();
            push_plain(&mut out, &mut plain_start, i);
            if def.keywords.contains(&word.as_str()) {
                out.push((i, j, Tok::Keyword));
            } else if j < n && chars[j] == '(' {
                out.push((i, j, Tok::Function));
            } else {
                out.push((i, j, Tok::Plain));
            }
            i = j;
            plain_start = i;
            matched = true;
        }
