/// Find the language for a file name.
pub fn language_for(name: &str, default_language: &str) -> String {
    let lower = name.to_lowercase();
    let fname = lower.rsplit('/').next().unwrap_or(&lower);
    for (lang, exts) in LANGUAGES.iter() {
        for e in exts.split(", ") {
            if e.is_empty() {
                continue;
            }
            if e.starts_with('.') {
                if fname == e.to_lowercase() || lower == e.to_lowercase() {
                    return lang.to_string();
                }
            } else if fname == e || fname.ends_with(&format!(".{}", e)) || fname == e.to_lowercase()
