// ---------------------------------------------------------------------------
// main processing
// ---------------------------------------------------------------------------

enum Mode {
    Outside,
    FileHeader,
    Hunk,
}

pub fn run(cfg: &Config, input: &str, color_only: bool) -> Vec<u8> {
    let mut p = Painter::new(cfg, color_only);
    let word_re = regex::Regex::new(&cfg.get_or("word-diff-regex", "\\w+")).ok();
    let mut mode = Mode::Outside;
    for raw_line in input.split('\n') {
        let line = raw_line.strip_suffix('\r').unwrap_or(raw_line);
        match mode {
            Mode::Outside => {
                if line.starts_with("diff --git ") {
                    p.begin_section(line);
                    mode = Mode::FileHeader;
                    continue;
                }
                if line.starts_with("diff ") {
                    p.begin_section(line);
                    mode = Mode::FileHeader;
                    continue;
                }
                if line.starts_with("--- ") {
                    p.begin_unified(line);
                    mode = Mode::FileHeader;
                    continue;
                }
                if line.starts_with("Only in ") {
                    p.emit_pass_line(line);
                    continue;
                }
                if p.commit_re_match(line) {
                    p.emit_commit_line(line);
                    continue;
                }
                p.emit_pass_line(line);
            }
            Mode::FileHeader => {
                if line.starts_with("@@") {
                    p.finish_header();
                    p.begin_hunk(line);
                    mode = Mode::Hunk;
                    continue;
                }
                if line.starts_with("diff --git ") || line.starts_with("diff ")
                    || line.starts_with("Only in ")
                    || line.starts_with("--- ")
                    || p.commit_re_match(line)
                {
                    p.finish_header();
                    mode = Mode::Outside;
                    p.process(line);
                    continue;
                }
                if line.starts_with("+++") {
                    p.set_plus_path(line);
                    continue;
                }
                p.header_line(line);
            }
            Mode::Hunk => {
                if line.starts_with("diff --git ") || line.starts_with("diff ")
                    || line.starts_with("Only in ")
                    || p.commit_re_match(line)
                {
                    p.flush_hunk();
                    mode = Mode::Outside;
                    p.process(line);
                    continue;
                }
                p.hunk_line(line, word_re.as_ref());
            }
        }
    }
    p.finish();
    p.out
}
