        let path = rest.split('\t').next().unwrap_or(rest).to_string();
        self.minus_path = Some(path);
        self.plus_path = None;
    }

    pub fn set_plus_path(&mut self, line: &str) {
        let rest = line.strip_prefix("+++ ").unwrap_or(line);
        let path = rest.split('\t').next().unwrap_or(rest).to_string();
        self.plus_path = Some(path);
