        if line.starts_with("--- ") {
            let rest = line["--- ".len()..].trim();
            let path = rest.split('\t').next().unwrap_or(rest);
            if path != "/dev/null" {
                self.minus_path = Some(path.to_string());
            }
            if let Some(sec) = &mut self.section {
                sec.minus_path = Some(path.to_string());
                if path == "/dev/null" {
                    sec.added = true;
                }
            }
        }
        if line.starts_with("+++ ") {
            self.set_plus_path(line);
            let rest = line["+++ ".len()..].trim();
            let path = rest.split('\t').next().unwrap_or(rest);
            if let Some(sec) = &mut self.section {
                sec.plus_path = Some(path.to_string());
                if path == "/dev/null" {
                    sec.removed = true;
                }
            }
        }
    }

    pub fn finish(&mut self) {
        self.flush_hunk();
        self.finish_header();
    }
}
