{"command": "cd /workspace && cat >> src/paint.rs <<'RSEOF'

impl<'a> Painter<'a> {
    fn strip_git_prefix(p: &str, minus: bool) -> String {
        if minus {
            p.strip_prefix("a/").unwrap_or(p).to_string()
        } else {
            p.strip_prefix("b/").unwrap_or(p).to_string()
        }
    }

    fn is_git_mode(&self) -> bool {
        self.git_mode
    }

    pub fn finish_header(&mut self) {
        if self.header_emitted {
            return;
        }
        let sec = match self.section.take() {
            Some(s) => s,
            None => {
                self.header_emitted = false;
                return;
            }
        };
        self.header_emitted = true;
        // blank line before the file header
        self.blank();
        let text = sec.header_text(self.cfg);
        let st = self.cfg.resolved_style("file-style");
        if !st.is_omitted() {
            let code = st.to_ansi();
            self.write_str(&code);
            self.write_str(&text);
            self.write_str("\x1b[0m\n");
        }
        // decoration
        let dst = self.cfg.resolved_style("file-decoration-style");
        let w = self.cfg.width;
        let cw = crate::utils::display_width(&text);
        self.emit_decoration(&dst, cw, false);
    }

    /// Emit the decoration lines for a content line of display width `cw`.
    /// `skip_before` skips the "ol" line (used when the content was already
    /// emitted).
    pub fn emit_decoration(&mut self, st: &Style, cw: usize, skip_box_middle: bool) {
        let _ = skip_box_middle;
        if st.is_empty() || st.is_omitted() {
            return;
        }
        let w = self.cfg.width;
        let code = st.to_ansi();
        let hz = "\u{2500}";
        let ol = st.overline_decoration;
        let ul = st.underline_decoration && !st.box_;
        let box_ = st.box_;
        if ol {
            self.write_str(&code);
            self.write_str(&hz.repeat(w));
            self.write_str("\x1b[0m\n");
        }
        if box_ {
            self.write_str(&code);
            self.write_str(&hz.repeat(cw));
            self.write_str("\x1b[0m");
            self.write_str(&code);
            self.write_str("\u{2510}");
            self.write_str("\x1b[0m\n");
        }
        self.pending_decoration_after = Some((st.clone(), cw, ul, box_));
    }

    pub fn emit_decoration_after(&mut self) {
        let (st, cw, ul, box_) = match self.pending_decoration_after.take() {
            Some(x) => x,
            None => return,
        };
        let w = self.cfg.width;
        let code = st.to_ansi();
        let hz = "\u{2500}";
        if box_ {
            self.write_str(&code);
            self.write_str(&hz.repeat(cw));
            self.write_str("\x1b[0m");
            self.write_str(&code);
            if ul {
                self.write_str("\u{2534}");
                self.write_str("\x1b[0m");
                self.write_str(&code);
                let rest = w.saturating_sub(cw + 1);
                self.write_str(&hz.repeat(rest));
                self.write_str("\x1b[0m\n");
            } else {
                self.write_str("\u{2518}");
                self.write_str("\x1b[0m\n");
            }
        } else if ul {
            self.write_str(&code);
            self.write_str(&hz.repeat(w));
            self.write_str("\x1b[0m\n");
        }
    }
}
