    // expect "-1,3 +1,4 @@"
    let mut it = body.split_whitespace();
    if let Some(m) = it.next() {
        let m = m.trim_start_matches('-');
        h.minus_start = m.split(',').next().and_then(|s| s.parse::<usize>().ok());
    }
    if let Some(p) = it.next() {
        let p = p.trim_start_matches('+');
        h.plus_start = p.split(',').next().and_then(|s| s.parse::<usize>().ok());
    }
    h
}

pub fn strip_prefix_path(p: &str) -> String {
    p.to_string()
}
