#[derive(Clone, Debug)]
pub struct HunkLine {
    pub kind: Kind,
    pub content: String,
    pub minus_ln: Option<usize>,
    pub plus_ln: Option<usize>,
}

impl<'a> Painter<'a> {
    pub fn hunk_line(&mut self, line: &str, word_re: Option<&regex::Regex>) {
        let _ = word_re;
        if line.starts_with("\\ ") || line == "\\ No newline at end of file" {
            self.buf.push(HunkLine {
                kind: Kind::Other,
                content: line.to_string(),
                minus_ln: None,
                plus_ln: None,
            });
            return;
        }
        let (kind, content) = if let Some(rest) = line.strip_prefix('-') {
            (Kind::Minus, rest.to_string())
        } else if let Some(rest) = line.strip_prefix('+') {
            (Kind::Plus, rest.to_string())
        } else if let Some(rest) = line.strip_prefix(' ') {
            (Kind::Zero, rest.to_string())
        } else {
            (Kind::Other, line.to_string())
        };
        let (minus_ln, plus_ln) = match kind {
            Kind::Minus => {
                self.minus_ln += 1;
                (Some(self.minus_ln), None)
            }
            Kind::Plus => {
                self.plus_ln += 1;
                (None, Some(self.plus_ln))
            }
            Kind::Zero => {
                self.minus_ln += 1;
                self.plus_ln += 1;
                (Some(self.minus_ln), Some(self.plus_ln))
            }
            Kind::Other => (None, None),
            _ => (None, None),
        };
        self.buf.push(HunkLine {
            kind,
            content,
            minus_ln,
            plus_ln,
        });
        if self.buf.len() >= 4096 {
            self.flush_hunk();
        }
    }

    pub fn flush_hunk(&mut self) {
        if self.buf.is_empty() {
            return;
        }
        let lines = std::mem::take(&mut self.buf);
        // pairing: align minus and plus lines by content
        let minus_idx: Vec<usize> = lines
            .iter()
            .enumerate()
            .filter(|(_, l)| l.kind == Kind::Minus)
            .map(|(i, _)| i)
            .collect();
        let plus_idx: Vec<usize> = lines
            .iter()
            .enumerate()
            .filter(|(_, l)| l.kind == Kind::Plus)
            .map(|(i, _)| i)
            .collect();
