{"command": "cd /workspace && cat > src/main.rs <<'RSEOF'
mod cli;
mod config;
mod gitconfig;
mod help;
mod langdata;
mod paint;
mod style;
mod syntax;
mod utils;

use clap::error::ErrorKind;

#[derive(Debug)]
enum Immediate {
    Help { long: bool },
    Version,
}

/// Mimic clap's left-to-right parsing to find a help/version flag that should
/// abort parsing immediately (clap exits on these before reporting later
/// errors).
fn scan_immediate(argv: &[String]) -> Option<Immediate> {
    let args = cli::ARGS;
    let mut i = 1;
    while i < argv.len() {
        let tok = &argv[i];
        if tok == "--" {
            return None;
        }
        if let Some(rest) = tok.strip_prefix("--") {
            let name = match rest.split_once('=') {
                Some((n, _)) => n,
                None => rest,
            };
            if name == "help" {
                return Some(Immediate::Help { long: true });
            }
            if name == "version" {
                return Some(Immediate::Version);
            }
            match args.iter().find(|a| a.long == name) {
                Some(spec) => {
                    if spec.takes_value && !rest.contains('=') {
                        i += 1; // consume value token
                    }
                }
                None => return None, // unknown option: let clap report it
            }
        } else if tok.starts_with('-') && tok.len() > 1 {
            let cluster: Vec<char> = tok[1..].chars().collect();
            let mut j = 0;
            while j < cluster.len() {
                let c = cluster[j];
                if c == 'h' {
                    return Some(Immediate::Help { long: cluster.len() > 1 });
                }
                if c == 'V' {
                    return Some(Immediate::Version);
                }
                match args.iter().find(|a| a.short == Some(c)) {
                    Some(spec) => {
                        if spec.takes_value {
                            if j + 1 < cluster.len() {
                                j = cluster.len();
                            } else {
                                i += 1;
                            }
                            break;
                        }
                        j += 1;
                    }
                    None => return None,
                }
            }
        }
        i += 1;
    }
    None
}

fn print_help(long: bool) -> ! {
    print!("{}", if long { help::LONG_HELP } else { help::SHORT_HELP });
    print!("\n");
    std::process::exit(0);
}

fn print_version() -> ! {
    println!("{} {}", help::NAME, help::VERSION);
    std::process::exit(0);
}

fn generate_completion(mut cmd: clap::Command, shell: &str) -> ! {
    use clap_complete::{generate, Shell};
    let sh = match shell {
        "bash" => Shell::Bash,
        "zsh" => Shell::Zsh,
        "fish" => Shell::Fish,
        "elvish" => Shell::Elvish,
        "powershell" => Shell::PowerShell,
        _ => std::process::exit(2),
    };
    generate(sh, &mut cmd, "delta", &mut std::io::stdout());
    std::process::exit(0);
}

fn main() {
    let argv: Vec<String> = std::env::args().collect();
    if let Some(imm) = scan_immediate(&argv) {
        match imm {
            Immediate::Help { long } => print_help(long),
            Immediate::Version => print_version(),
        }
    }
    let cmd = cli::build();
    let m = match cmd.clone().try_get_matches() {
        Ok(m) => m,
        Err(e) => match e.kind() {
            ErrorKind::DisplayHelp => print_help(false),
            ErrorKind::DisplayVersion => print_version(),
            _ => e.exit(),
        },
    };
    if let Some(sh) = m.get_one::<String>("generate_completion") {
        generate_completion(cmd, sh);
    }
    let cfg = config::build_config(&m);
    // meta commands
    if m.get_flag("list_languages") {
        crate::commands::list_languages();
        return;
    }
    if m.get_flag("list_syntax_themes") {
        crate::commands::list_syntax_themes();
        return;
    }
    if m.get_flag("show_colors") {
        crate::commands::show_colors();
        return;
    }
    if m.get_flag("show_config") {
        crate::commands::show_config(&cfg);
        return;
    }
    // diff two files
    let minus_file = m.get_one::<String>("minus_file");
    let plus_file = m.get_one::<String>("plus_file");
    let input = match (minus_file, plus_file) {
        (Some(a), Some(b)) => crate::commands::diff_two_files(&cfg, m, a, b),
        _ => {
            let mut s = String::new();
            use std::io::Read;
            let _ = std::io::stdin().read_to_string(&mut s);
            s
        }
    };
    let color_only = m.get_flag("color_only");
    let out = paint::run(&cfg, &input, color_only);
    use std::io::Write;
    let stdout = std::io::stdout();
    let mut lock = stdout.lock();
    let _ = lock.write_all(&out);
    let _ = lock.flush();
}
