                        return Err(format!("Invalid color or style attribute: {}", tok));
                    }
                    st.box_ = false;
                    st.underline_decoration = false;
                    st.overline_decoration = false;
                }
            }
            continue;
        }
        if let Some(code) = attr_code(tok) {
            st.attrs |= code;
            continue;
        }
        let color = match parse_color(tok, true_color) {
            Some(c) => c,
            None => return Err(format!("Invalid color or style attribute: {}", tok)),
        };
        ncolors += 1;
        if ncolors > 2 {
            return Err(format!(
                "Invalid style string: {}. See the STYLES section of delta --help.",
                s
            ));
        }
        if ncolors == 1 {
            st.fg = Some(color);
        } else {
            st.bg = Some(color);
        }
    }
    Ok(st)
}

pub fn allows_box_token(is_decoration: bool) -> bool {
    is_decoration || BOX_OK
}

pub static mut BOX_OK: bool = false;
