//! Meta commands: --list-languages, --list-syntax-themes, --show-config, ...

use crate::config::Config;
use crate::langdata::{LANGUAGES, THEMES};

/// Wrap text to `width` columns with `indent` on continuation lines,
/// preserving trailing separators.
fn wrap_items(items: &[String], indent: usize, width: usize, sep: &str) -> Vec<String> {
    let mut out: Vec<String> = Vec::new();
    let mut cur = String::new();
    let mut first = true;
    for it in items {
        let piece = if items.last() == Some(it) {
            it.clone()
        } else {
            format!("{}{}", it, sep)
        };
        if !first && crate::utils::display_width(&cur) + crate::utils::display_width(&piece) > width
        {
            out.push(cur.clone());
            cur = String::new();
        }
        cur.push_str(&piece);
        first = false;
    }
    out.push(cur);
    out
}

pub fn list_languages() {
    let mut out = String::new();
    for (name, exts) in LANGUAGES.iter() {
        let items: Vec<String> = exts.split(", ").map(|s| s.to_string()).collect();
        let lines = wrap_items(&items, 26, 99, ", ");
        for (i, l) in lines.iter().enumerate() {
            if i == 0 {
                out.push_str(&format!("{:<26}", name));
            } else {
                out.push_str(&" ".repeat(26));
            }
            // color each extension green
            let mut first = true;
            for ext in l.split(", ") {
                if ext.is_empty() {
                    continue;
                }
                if !first {
                    out.push_str(", ");
                }
                out.push_str("\x1b[32m");
                out.push_str(ext);
                out.push_str("\x1b[0m");
                first = false;
            }
            out.push('\n');
        }
    }
    print!("{}", out);
}

pub fn list_syntax_themes() {
    for (kind, name) in THEMES.iter() {
        println!("{}\t{}", kind, name);
    }
}

pub fn show_config(cfg: &Config) {
    let mut lines: Vec<(String, String)> = Vec::new();
