        format!("{}{}\x1b[0m", s.to_ansi(), s.display())
    };
    push(&mut lines, "commit-style", format!("{}", cfg.get_or("commit-style", "raw")));
    push(&mut lines, "file-style", st(cfg, "file-style"));
    push(&mut lines, "hunk-header-style", st(cfg, "hunk-header-style"));
