    push(&mut lines, "minus-non-emph-style", st(cfg, "minus-non-emph-style"));
    push(&mut lines, "minus-emph-style", st(cfg, "minus-emph-style"));
    push(&mut lines, "minus-empty-line-marker-style", st(cfg, "minus-empty-line-marker-style"));
    push(&mut lines, "zero-style", st(cfg, "zero-style"));
    push(&mut lines, "plus-style", st(cfg, "plus-style"));
    push(&mut lines, "plus-non-emph-style", st(cfg, "plus-non-emph-style"));
    push(&mut lines, "plus-emph-style", st(cfg, "plus-emph-style"));
