/// Run `git diff` (or `diff`) on two files and return its output.
pub fn diff_two_files(
    cfg: &Config,
    m: &clap::ArgMatches,
    a: &str,
    b: &str,
) -> String {
    let diff_args = m.get_one::<String>("diff_args").cloned().unwrap_or_default();
    let extra: Vec<&str> = diff_args.split_whitespace().collect();
    // try git first
    let git_ok = std::process::Command::new("git").arg("--version").output().map(|o| o.status.success()).unwrap_or(false);
    if git_ok {
        let mut cmdargs: Vec<String> = vec!["diff".to_string(), "--no-index".to_string(), "--color".to_string()];
        for e in &extra {
