pub fn build_config(m: &clap::ArgMatches) -> Config {
    let mut map: std::collections::HashMap<String, String> = std::collections::HashMap::new();
    for (k, v) in default_values() {
        map.insert(k.to_string(), v);
    }
    // ---- terminal width / true color / dark-light
    let is_tty = crate::utils::stdout_is_tty();
    let (term_width, _) = crate::utils::terminal_size();
    let dark = detect_dark_light(&m, map.clone());
    let true_color = match m.get_one::<String>("true_color").map(|s| s.as_str()) {
        Some("always") => true,
        Some("never") => false,
        _ => std::env::var("COLORTERM")
            .map(|v| v == "truecolor" || v == "24bit")
            .unwrap_or(false),
    };
    let width = match m.get_one::<String>("width") {
        Some(w) => parse_width(w, term_width),
        None => term_width.unwrap_or(80),
    };
    let syntax_theme = m
        .get_one::<String>("syntax_theme")
        .cloned()
        .unwrap_or_default();
    let cfg = Config {
        map,
        dark,
        true_color,
        width: if width == 0 { 80 } else { width },
    };
    let _ = (is_tty, syntax_theme);
    cfg
}

fn parse_width(w: &str, term_width: Option<usize>) -> usize {
    if w == "variable" {
        return 0;
    }
    // handles "80", "-2", "74-2"
    if let Some(stripped) = w.strip_prefix('-') {
        if let Ok(n) = stripped.parse::<usize>() {
            let base = term_width.unwrap_or(80);
            return base.saturating_sub(n);
        }
        return 80;
    }
    if let Some((a, b)) = w.split_once('-') {
        if let (Ok(base), Ok(n)) = (a.trim().parse::<usize>(), b.trim().parse::<usize>()) {
            return base.saturating_sub(n);
        }
    }
    w.parse::<usize>().unwrap_or(80)
}

fn detect_dark_light(m: &clap::ArgMatches, map: std::collections::HashMap<String, String>) -> bool {
    if let Some(d) = m.get_one::<String>("detect_dark_light") {
        let _ = d;
    }
    // default: dark
    let _ = map;
    true
}
