//! Diff parser and painter.

use crate::config::Config;
use crate::style::{Color, Style};
use std::io::Write;

#[derive(Clone, Debug, PartialEq)]
pub enum Kind {
    Commit,
    FileHeader,
    HunkHeader,
    Minus,
    Plus,
    Zero,
    Other,
}

#[derive(Clone, Debug, Default)]
pub struct HunkHeader {
    pub minus_start: Option<usize>,
    pub plus_start: Option<usize>,
    pub raw: String,
}

#[derive(Default)]
pub struct FileSection {
    pub minus_path: Option<String>,
    pub plus_path: Option<String>,
    pub added: bool,
    pub removed: bool,
    pub renamed: bool,
    pub copied: bool,
    pub mode_change: Option<String>,
    pub rename_from: Option<String>,
    pub rename_to: Option<String>,
    pub copy_from: Option<String>,
    pub copy_to: Option<String>,
}

impl FileSection {
    /// Strip the a/ and b/ prefixes used by `git diff`.
    pub fn strip_git(p: &str, minus: bool) -> String {
        if minus {
            p.strip_prefix("a/").unwrap_or(p).to_string()
        } else {
            p.strip_prefix("b/").unwrap_or(p).to_string()
        }
    }

    pub fn header_text(&self, cfg: &Config, git_mode: bool) -> String {
        let right_arrow = cfg.get_or("right-arrow", "\u{27f6}  ");
        let added_label = cfg.get_or("file-added-label", "added:");
        let removed_label = cfg.get_or("file-removed-label", "removed:");
        let renamed_label = cfg.get_or("file-renamed-label", "renamed:");
        let copied_label = cfg.get_or("file-copied-label", "copied:");
        let modified_label = cfg.get_or("file-modified-label", "");
        let strip = |p: &String, minus: bool| -> String {
            if git_mode {
                FileSection::strip_git(p, minus)
            } else {
                p.clone()
            }
        };
        let mut s = String::new();
        if let (Some(from), Some(to)) = (&self.rename_from, &self.rename_to) {
            s.push_str(&renamed_label);
            s.push(' ');
            s.push_str(from);
            s.push(' ');
            s.push_str(&right_arrow);
            s.push_str(to);
        } else if let (Some(from), Some(to)) = (&self.copy_from, &self.copy_to) {
            s.push_str(&copied_label);
            s.push(' ');
            s.push_str(from);
            s.push(' ');
            s.push_str(&right_arrow);
            s.push_str(to);
        } else if self.removed {
            s.push_str(&removed_label);
            s.push(' ');
            if let Some(p) = &self.minus_path {
                s.push_str(&strip(p, true));
            }
        } else if self.added {
            s.push_str(&added_label);
            s.push(' ');
            if let Some(p) = &self.plus_path {
                s.push_str(&strip(p, false));
            }
        } else {
            let mp = self.minus_path.clone().unwrap_or_default();
            let pp = self.plus_path.clone().unwrap_or_default();
            let mp = strip(&mp, true);
            let pp = strip(&pp, false);
            if !mp.is_empty() && mp != pp {
                s.push_str(&mp);
                s.push(' ');
                s.push_str(&right_arrow);
                s.push_str(&pp);
            } else if !pp.is_empty() {
                s.push_str(&modified_label);
                if !modified_label.is_empty() {
                    s.push(' ');
                }
                s.push_str(&pp);
            } else if !mp.is_empty() {
                s.push_str(&modified_label);
                if !modified_label.is_empty() {
                    s.push(' ');
                }
                s.push_str(&mp);
            }
        }
        if let Some(m) = &self.mode_change {
            s.push_str(" (");
            s.push_str(m);
            s.push(')');
        }
        s
    }

    pub fn display_path(&self, git_mode: bool) -> String {
        if let (Some(_f), Some(t)) = (&self.rename_from, &self.rename_to) {
            return t.clone();
        }
        if let (Some(_f), Some(t)) = (&self.copy_from, &self.copy_to) {
            return t.clone();
        }
        match (&self.plus_path, &self.minus_path) {
            (Some(p), _) => {
                if git_mode {
                    FileSection::strip_git(p, false)
                } else {
                    p.clone()
                }
            }
            (None, Some(p)) => {
                if git_mode {
                    FileSection::strip_git(p, true)
                } else {
                    p.clone()
                }
            }
            _ => String::new(),
        }
    }
}

#[derive(Clone, Debug)]
pub struct PendingLine {
    pub kind: Kind,
    pub content: String,
    pub minus_ln: Option<usize>,
    pub plus_ln: Option<usize>,
}

pub struct Painter<'a> {
    pub cfg: &'a Config,
    pub out: Vec<u8>,
    pub minus_path: Option<String>,
    pub plus_path: Option<String>,
    pub section: Option<FileSection>,
    pub saw_hunk: bool,
    pub buf: Vec<PendingLine>,
    pub minus_ln: usize,
    pub plus_ln: usize,
    pub hunk_header: HunkHeader,
    pub line_numbers: bool,
    pub side_by_side: bool,
    pub keep_markers: bool,
    pub color_only: bool,
    pub first_file: bool,
    pub git_mode: bool,
    pub header_emitted: bool,
    pub have_section: bool,
}

enum Mode {
    Outside,
    FileHeader,
    Hunk,
}

impl<'a> Painter<'a> {
    pub fn new(cfg: &'a Config, color_only: bool) -> Self {
        Painter {
            cfg,
            out: Vec::new(),
            minus_path: None,
            plus_path: None,
            section: None,
            saw_hunk: false,
            buf: Vec::new(),
            minus_ln: 0,
            plus_ln: 0,
            hunk_header: HunkHeader::default(),
            line_numbers: cfg.get_bool("line-numbers", false),
            side_by_side: cfg.get_bool("side-by-side", false),
            keep_markers: cfg.get_bool("keep-plus-minus-markers", false),
            color_only,
            first_file: true,
            git_mode: false,
            header_emitted: false,
            have_section: false,
        }
    }

    pub fn write_str(&mut self, s: &str) {
        self.out.extend_from_slice(s.as_bytes());
    }
    pub fn write_line(&mut self, s: &str) {
        self.out.extend_from_slice(s.as_bytes());
        self.out.push(b'\n');
    }
    pub fn blank(&mut self) {
        self.out.push(b'\n');
    }

    pub fn resolve_color(&self, c: &Color) -> Color {
        match c {
            Color::Rgb(r, g, b) => {
                if self.cfg.true_color {
                    Color::Rgb(*r, *g, *b)
                } else {
                    Color::Ansi256(crate::style::rgb_to_ansi256(*r, *g, *b))
                }
            }
            other => other.clone(),
        }
    }

    pub fn styled(&self, st: &Style, s: &str) -> String {
        if st.is_omitted() {
            return String::new();
        }
        format!("{}{}\x1b[0m", st.to_ansi(), s)
    }

    pub fn commit_re_match(&self, line: &str) -> bool {
        let re = self.cfg.get_or("commit-regex", "^commit ");
        regex::Regex::new(&re)
            .map(|r| r.is_match(line))
            .unwrap_or(false)
    }

    pub fn emit_pass_line(&mut self, line: &str) {
        self.write_line(line);
    }

    pub fn emit_commit_line(&mut self, line: &str) {
        let st = self.cfg.resolved_style("commit-style");
        if st.is_omitted() {
            return;
        }
        if st.raw {
            self.write_line(line);
            return;
        }
        let code = st.to_ansi();
        self.write_str(&code);
        self.write_str(line);
        self.write_str("\x1b[0m\n");
    }

    pub fn process(&mut self, line: &str) {
        if line.starts_with("diff --git ") || line.starts_with("diff ") {
            self.begin_section(line);
        } else if line.starts_with("--- ") {
            self.begin_unified(line);
        } else if line.starts_with("Only in ") {
            self.emit_pass_line(line);
        } else if self.commit_re_match(line) {
            self.emit_commit_line(line);
        } else {
            self.emit_pass_line(line);
        }
    }

    pub fn begin_section(&mut self, line: &str) {
        self.flush_hunk();
        self.finish_header();
        self.git_mode = line.starts_with("diff --git ");
        self.header_emitted = false;
        self.have_section = true;
        self.section = Some(FileSection::default());
        let rest = line
            .strip_prefix("diff --git ")
            .unwrap_or(line.strip_prefix("diff ").unwrap_or(line));
        let toks: Vec<&str> = rest.split_whitespace().collect();
        if toks.len() >= 2 {
            let a = toks[toks.len() - 2];
            let b = toks[toks.len() - 1];
            if let Some(sec) = &mut self.section {
                sec.minus_path = Some(a.to_string());
                sec.plus_path = Some(b.to_string());
            }
            self.minus_path = Some(a.to_string());
            self.plus_path = Some(b.to_string());
        }
    }

    pub fn begin_unified(&mut self, line: &str) {
        self.flush_hunk();
        self.finish_header();
        self.git_mode = false;
        self.header_emitted = false;
        self.have_section = true;
        self.section = Some(FileSection::default());
        let rest = line.strip_prefix("--- ").unwrap_or(line);
        let path = rest.split('\t').next().unwrap_or(rest).to_string();
        if let Some(sec) = &mut self.section {
            sec.minus_path = Some(path.clone());
        }
        self.minus_path = Some(path);
    }

    pub fn header_line(&mut self, line: &str) {
        if let Some(sec) = &mut self.section {
            if line.starts_with("new file mode ") {
                sec.added = true;
            } else if line.starts_with("deleted file mode ") {
                sec.removed = true;
            } else if line.starts_with("similarity index ")
                || line.starts_with("dissimilarity index ")
                || line.starts_with("index ")
                || line.starts_with("GIT binary patch")
                || line.starts_with("Binary files ")
            {
                // ignore
            } else if let Some(rest) = line.strip_prefix("rename from ") {
                sec.rename_from = Some(rest.to_string());
                sec.renamed = true;
            } else if let Some(rest) = line.strip_prefix("rename to ") {
                sec.rename_to = Some(rest.to_string());
                sec.renamed = true;
            } else if let Some(rest) = line.strip_prefix("copy from ") {
                sec.copy_from = Some(rest.to_string());
                sec.copied = true;
            } else if let Some(rest) = line.strip_prefix("copy to ") {
                sec.copy_to = Some(rest.to_string());
                sec.copied = true;
            } else if line.starts_with("old mode ") {
                // ignore (handled with the new mode)
            } else if line.starts_with("new mode ") {
                let mode = line["new mode ".len()..].trim();
                let bytes = mode.as_bytes();
                let exec = bytes.len() >= 3 && bytes[2] != b'0';
                if exec {
                    sec.mode_change = Some("mode +x".to_string());
                }
            }
        }
        if line.starts_with("--- ") {
            let rest = line["--- ".len()..].trim_end();
            let path = rest.split('\t').next().unwrap_or(rest).to_string();
            if let Some(sec) = &mut self.section {
                sec.minus_path = Some(path.clone());
                if self.git_mode && path == "/dev/null" {
                    sec.added = true;
                }
            }
            self.minus_path = Some(path);
        }
        if line.starts_with("+++ ") {
            let rest = line["+++ ".len()..].trim_end();
            let path = rest.split('\t').next().unwrap_or(rest).to_string();
            if let Some(sec) = &mut self.section {
                sec.plus_path = Some(path.clone());
                if self.git_mode && path == "/dev/null" {
                    sec.removed = true;
                }
            }
            self.plus_path = Some(path);
        }
    }

    pub fn finish_header(&mut self) {
        if self.header_emitted || !self.have_section {
            return;
        }
        let sec = match self.section.take() {
            Some(s) => s,
            None => return,
        };
        self.header_emitted = true;
        self.have_section = false;
        self.blank();
        let text = sec.header_text(self.cfg, self.git_mode);
        let st = self.cfg.resolved_style("file-style");
        let dst = self.cfg.resolved_style("file-decoration-style");
        self.file_name = sec.display_path(self.git_mode);
        if st.is_omitted() {
            self.emit_decorated(&text, &st, &crate::style::Style::default());
        } else {
            self.emit_decorated(&text, &st, &dst);
        }
    }

    /// Emit a content line surrounded by decoration lines.
    pub fn emit_decorated(&mut self, text: &str, content: &Style, decor: &Style) {
        let w = self.cfg.width;
        let cw = crate::utils::display_width(text);
        let code = decor.to_ansi();
        let hz = "\u{2500}";
        let use_decor = !decor.is_empty() && !decor.is_omitted();
        if use_decor && decor.overline_decoration && !decor.box_ {
            self.write_str(&code);
            self.write_str(&hz.repeat(w));
            self.write_str("\x1b[0m\n");
        }
        if use_decor && decor.box_ {
            self.write_str(&code);
            self.write_str(&hz.repeat(cw));
            self.write_str("\x1b[0m");
            self.write_str(&code);
            self.write_str("\u{2510}");
            self.write_str("\x1b[0m\n");
        }
        if !content.is_omitted() {
            let ccode = content.to_ansi();
            self.write_str(&ccode);
            self.write_str(text);
            self.write_str("\x1b[0m");
        }
        if use_decor && decor.box_ {
            self.write_str(&code);
            self.write_str("\u{2502}");
            self.write_str("\x1b[0m");
        }
        self.write_str("\n");
        if use_decor && decor.box_ {
            self.write_str(&code);
            self.write_str(&hz.repeat(cw));
            self.write_str("\x1b[0m");
            self.write_str(&code);
            if decor.underline_decoration {
                self.write_str("\u{2534}");
                self.write_str("\x1b[0m");
                self.write_str(&code);
                let rest = w.saturating_sub(cw + 1);
                self.write_str(&hz.repeat(rest));
                self.write_str("\x1b[0m\n");
            } else {
                self.write_str("\u{2518}");
                self.write_str("\x1b[0m\n");
            }
        } else if use_decor && decor.underline_decoration {
            self.write_str(&code);
            self.write_str(&hz.repeat(w));
            self.write_str("\x1b[0m\n");
        }
    }

    pub fn begin_hunk(&mut self, line: &str) {
        self.header_emitted = false;
        self.blank();
        self.hunk_header = parse_hunk_header(line);
        let st = self.cfg.resolved_style("hunk-header-style");
        if st.is_omitted() {
            self.minus_ln = self.hunk_header.minus_start.unwrap_or(0);
            self.plus_ln = self.hunk_header.plus_start.unwrap_or(0);
            return;
        }
        let hh_dec = self.cfg.resolved_style("hunk-header-decoration-style");
        let ln_style = self.cfg.resolved_style("hunk-header-line-number-style");
        let file_style = self.cfg.resolved_style("hunk-header-file-style");
        let mut text = String::new();
        if st.line_number {
            let n = self.hunk_header.plus_start.unwrap_or(0);
            text.push_str(&self.styled(&ln_style, &format!("{}", n)));
            if st.file {
                text.push(':');
            }
            text.push_str(": ");
        }
        if st.file {
            text.push_str(&self.styled(&file_style, &self.file_name()));
        }
        self.emit_decorated(&text, &st, &hh_dec);
        self.minus_ln = self.hunk_header.minus_start.unwrap_or(0);
        self.plus_ln = self.hunk_header.plus_start.unwrap_or(0);
        self.saw_hunk = true;
    }

    pub fn file_name(&self) -> String {
        if let Some(sec) = &self.section {
            return sec.display_path(self.git_mode);
        }
        match (&self.plus_path, &self.minus_path) {
            (Some(p), _) => p.clone(),
            (None, Some(p)) => p.clone(),
            _ => String::new(),
        }
    }

    pub fn current_language(&self) -> String {
        let def = self.cfg.get_or("default-language", "txt");
        let path = self.file_name();
        crate::syntax::language_for(&path, &def)
    }

    pub fn hunk_line(&mut self, line: &str) {
        if line.starts_with("\\ ") {
            self.buf.push(PendingLine {
                kind: Kind::Other,
                content: line.to_string(),
                minus_ln: None,
                plus_ln: None,
            });
            return;
        }
        let (kind, content) = if let Some(rest) = line.strip_prefix('-') {
            (Kind::Minus, rest.to_string())
        } else if let Some(rest) = line.strip_prefix('+') {
            (Kind::Plus, rest.to_string())
        } else if let Some(rest) = line.strip_prefix(' ') {
            (Kind::Zero, rest.to_string())
        } else {
            (Kind::Other, line.to_string())
        };
        let (minus_ln, plus_ln) = match kind {
            Kind::Minus => {
                self.minus_ln += 1;
                (Some(self.minus_ln), None)
            }
            Kind::Plus => {
                self.plus_ln += 1;
                (None, Some(self.plus_ln))
            }
            Kind::Zero => {
                self.minus_ln += 1;
                self.plus_ln += 1;
                (Some(self.minus_ln), Some(self.plus_ln))
            }
            _ => (None, None),
        };
        self.buf.push(PendingLine {
            kind,
            content,
            minus_ln,
            plus_ln,
        });
        if self.buf.len() >= 1024 {
            self.flush_hunk();
        }
    }

    pub fn flush_hunk(&mut self) {
        if self.buf.is_empty() {
            return;
        }
        let lines = std::mem::take(&mut self.buf);
        let minus_idx: Vec<usize> = lines
            .iter()
            .enumerate()
            .filter(|(_, l)| l.kind == Kind::Minus)
            .map(|(i, _)| i)
            .collect();
        let plus_idx: Vec<usize> = lines
            .iter()
            .enumerate()
            .filter(|(_, l)| l.kind == Kind::Plus)
            .map(|(i, _)| i)
            .collect();
        let a: Vec<&str> = minus_idx.iter().map(|&i| lines[i].content.as_str()).collect();
        let b: Vec<&str> = plus_idx.iter().map(|&i| lines[i].content.as_str()).collect();
        let ops = diff_tokens(&a, &b);
        let mut emph: std::collections::HashMap<usize, Vec<(usize, usize)>> =
            std::collections::HashMap::new();
        let max_dist = self.cfg.get_float("max-line-distance", 0.6);
        let word_re = regex::Regex::new(&self.cfg.get_or("word-diff-regex", "\\w+")).ok();
        for op in &ops {
            if let (Op::Equal, i, j) = op {
                let mi = minus_idx[*i];
                let pi = plus_idx[*j];
                if let Some((_, (d, ins))) =
                    line_emphasis(&lines[mi].content, &lines[pi].content, max_dist, word_re.as_ref())
                {
                    emph.insert(mi, d);
                    emph.insert(pi, ins);
                }
            }
        }
        for (i, l) in lines.iter().enumerate() {
            match l.kind {
                Kind::Other => self.write_line(&l.content),
                _ => {
                    let e = emph.get(&i).cloned().unwrap_or_default();
                    self.emit_diff_line(l, &e);
                }
            }
        }
    }

    pub fn emit_diff_line(&mut self, l: &PendingLine, emph_ranges: &[(usize, usize)]) {
        let base_name = match l.kind {
            Kind::Minus => "minus-style",
            Kind::Plus => "plus-style",
            _ => "zero-style",
        };
        let emph_name = match l.kind {
            Kind::Minus => "minus-emph-style",
            _ => "plus-emph-style",
        };
        let base = self.cfg.resolved_style(base_name);
        if base.raw {
            self.write_line(&l.content);
            return;
        }
        let emph_style = self.cfg.resolved_style(emph_name);
        let ws_style = self.cfg.resolved_style("whitespace-error-style");
        let lang = self.current_language();
        let theme_name = {
            let t = self.cfg.get_or("syntax-theme", "");
            if t.is_empty() {
                if self.cfg.dark {
                    crate::config::DEFAULT_SYNTAX_THEME_DARK
                } else {
                    crate::config::DEFAULT_SYNTAX_THEME_LIGHT
                }
            } else {
                Box::leak(t.to_string().into_boxed_str())
            }
        };
        let theme = crate::syntax::theme_colors(theme_name);
        let max_syntax = self.cfg.get_int("max-syntax-highlighting-length", 400);
        let syn = match &theme {
            Some(t) => crate::syntax::highlight(&lang, &l.content, max_syntax, t),
            None => vec![],
        };
        let chars: Vec<char> = l.content.chars().collect();
        let n = chars.len();
        let mut styles: Vec<Style> = vec![base.clone(); n];
        for (s, e, tok) in &syn {
            for i in (*s).min(n)..(*e).min(n) {
                if styles[i].fg == Some(Color::Syntax) {
                    styles[i].fg = Some(crate::syntax::color_for(*tok, self.cfg.true_color));
                }
            }
        }
        for (s, e) in emph_ranges {
            for i in (*s).min(n)..(*e).min(n) {
                let mut st = emph_style.clone();
                if st.fg == Some(Color::Syntax) {
                    st.fg = styles[i].fg.clone();
                }
                styles[i] = st;
            }
        }
        if l.kind == Kind::Plus {
            let mut i = n;
            while i > 0 && (chars[i - 1] == ' ' || chars[i - 1] == '\t') {
                i -= 1;
            }
            for j in i..n {
                let mut st = ws_style.clone();
                if st.fg == Some(Color::Syntax) {
                    st.fg = styles[j].fg.clone();
                }
                styles[j] = st;
            }
        }
        let marker = match l.kind {
            Kind::Minus => "-",
            Kind::Plus => "+",
            Kind::Zero => " ",
            _ => "",
        };
        let keep = self.keep_markers || self.color_only;
        if keep && l.kind != Kind::Zero {
            let st0 = styles.first().cloned().unwrap_or_else(|| base.clone());
            self.write_str(&st0.to_ansi());
            self.write_str(marker);
        } else if keep {
            self.write_str(" ");
        }
        let mut st = AnsiState::default();
        let mut i = 0;
        while i < n {
            let s = styles[i].clone();
            let mut j = i + 1;
            while j < n && styles[j] == s {
                j += 1;
            }
            let text: String = chars[i..j].iter().collect();
            let target = AnsiState {
                attrs: s.attrs & !crate::style::ATTR_OMIT,
                fg: s.fg.clone().map(|c| self.resolve_color(&c)),
                bg: s.bg.clone().map(|c| self.resolve_color(&c)),
            };
            let t = st.transition(&target);
            if !t.is_empty() {
                self.write_str(&t);
            }
            self.write_str(&text);
            st = target;
            i = j;
        }
        let empty = AnsiState::default();
        let t = st.transition(&empty);
        self.write_str(&t);
        if let Some(bg) = &base.bg {
            if bg != &Color::Normal {
                let fill = AnsiState {
                    attrs: 0,
                    fg: None,
                    bg: Some(self.resolve_color(bg)),
                };
                let t2 = AnsiState::default().transition(&fill);
                self.write_str(&t2);
                self.write_str("\x1b[0K");
                self.write_str("\x1b[0m");
            }
        }
        self.write_str("\n");
    }

    pub fn finish(&mut self) {
        self.flush_hunk();
        self.finish_header();
    }
}

#[derive(Clone, PartialEq, Default, Debug)]
pub struct AnsiState {
    pub attrs: u32,
    pub fg: Option<Color>,
    pub bg: Option<Color>,
}

impl AnsiState {
    /// Emit the escape sequence transitioning from `self` to `other`.
    pub fn transition(&self, other: &AnsiState) -> String {
        let need_reset = (self.attrs != 0 && other.attrs == 0)
            || (self.bg.is_some() && other.bg.is_none())
            || (self.fg.is_some() && other.fg.is_none());
        if !need_reset && self.attrs == other.attrs {
            let mut codes: Vec<String> = Vec::new();
            if self.bg != other.bg {
                if let Some(b) = &other.bg {
                    if let Some(s) = b.sgr_bg() {
                        codes.push(s);
                    }
                }
            }
            if self.fg != other.fg {
                if let Some(f) = &other.fg {
                    if let Some(s) = f.sgr_fg() {
                        codes.push(s);
                    }
                }
            }
            if codes.is_empty() {
                return String::new();
            }
            return format!("\x1b[{}m", codes.join(";"));
        }
        let mut codes: Vec<String> = Vec::new();
        for (flag, code) in [
            (crate::style::ATTR_BOLD, "1"),
            (crate::style::ATTR_DIM, "2"),
            (crate::style::ATTR_ITALIC, "3"),
            (crate::style::ATTR_BLINK, "5"),
            (crate::style::ATTR_REVERSE, "7"),
            (crate::style::ATTR_STRIKE, "9"),
            (crate::style::ATTR_UNDERLINE, "4"),
        ] {
            if other.attrs & flag != 0 {
                codes.push(code.to_string());
            }
        }
        if let Some(b) = &other.bg {
            if let Some(s) = b.sgr_bg() {
                codes.push(s);
            }
        }
        if let Some(f) = &other.fg {
            if let Some(s) = f.sgr_fg() {
                codes.push(s);
            }
        }
        if codes.is_empty() {
            return "\x1b[0m".to_string();
        }
        format!("\x1b[0m\x1b[{}m", codes.join(";"))
    }
}

// ---------------------------------------------------------------------------
// tokenization and within-line diff
// ---------------------------------------------------------------------------

pub fn tokenize(line: &str, word_re: &regex::Regex) -> Vec<(usize, usize)> {
    let mut out = Vec::new();
    let chars: Vec<char> = line.chars().collect();
    let mut byte_off = 0usize;
    let mut i = 0usize;
    while i < chars.len() {
        let rest = &line[byte_off..];
        if let Some(m) = word_re.find(rest) {
            if m.start() == 0 {
                let len = m.as_str().chars().count();
                if len > 0 {
                    out.push((i, i + len));
                    i += len;
                    byte_off += m.as_str().len();
                    continue;
                }
            }
        }
        out.push((i, i + 1));
        i += 1;
        byte_off += chars[i - 1].len_utf8();
    }
    out
}

pub fn is_word_token(line: &str, tok: &(usize, usize), word_re: &regex::Regex) -> bool {
    let s: String = line.chars().skip(tok.0).take(tok.1 - tok.0).collect();
    word_re.is_match(&s)
}

pub fn lcs_len<T: PartialEq + Copy>(a: &[T], b: &[T]) -> usize {
    let n = a.len();
    let m = b.len();
    if n == 0 || m == 0 {
        return 0;
    }
    let mut prev = vec![0usize; m + 1];
    let mut cur = vec![0usize; m + 1];
    for i in 1..=n {
        for j in 1..=m {
            cur[j] = if a[i - 1] == b[j - 1] {
                prev[j - 1] + 1
            } else {
                std::cmp::max(prev[j], cur[j - 1])
            };
        }
        std::mem::swap(&mut prev, &mut cur);
    }
    prev[m]
}

#[derive(Clone, Debug, PartialEq)]
pub enum Op {
    Equal,
    Delete,
    Insert,
}

/// Diff two sequences, returning ops (Delete consumes a, Insert consumes b).
pub fn diff_tokens<T: PartialEq + Copy>(a: &[T], b: &[T]) -> Vec<(Op, usize, usize)> {
    let n = a.len();
    let m = b.len();
    let mut table = vec![vec![0usize; m + 1]; n + 1];
    for i in (0..n).rev() {
        for j in (0..m).rev() {
            table[i][j] = if a[i] == b[j] {
                table[i + 1][j + 1] + 1
            } else {
                std::cmp::max(table[i + 1][j], table[i][j + 1])
            };
        }
    }
    let mut ops = Vec::new();
    let mut i = 0;
    let mut j = 0;
    while i < n && j < m {
        if a[i] == b[j] {
            ops.push((Op::Equal, i, j));
            i += 1;
            j += 1;
        } else if table[i + 1][j] >= table[i][j + 1] {
            ops.push((Op::Delete, i, j));
            i += 1;
        } else {
            ops.push((Op::Insert, i, j));
            j += 1;
        }
    }
    while i < n {
        ops.push((Op::Delete, i, j));
        i += 1;
    }
    while j < m {
        ops.push((Op::Insert, i, j));
        j += 1;
    }
    ops
}

pub fn merge_ranges(mut v: Vec<(usize, usize)>) -> Vec<(usize, usize)> {
    v.sort();
    let mut out: Vec<(usize, usize)> = Vec::new();
    for (s, e) in v {
        if let Some(last) = out.last_mut() {
            if s <= last.1 {
                last.1 = std::cmp::max(last.1, e);
                continue;
            }
        }
        out.push((s, e));
    }
    out
}

/// Compute the within-line emphasis regions for a pair of homologous lines.
pub fn line_emphasis(
    a: &str,
    b: &str,
    max_distance: f64,
    word_re: Option<&regex::Regex>,
) -> Option<(Vec<(usize, usize)>, Vec<(usize, usize)>)> {
    let word_re = word_re?;
    let ta = tokenize(a, &word_re);
    let tb = tokenize(b, &word_re);
    let words_a: Vec<usize> = (0..ta.len())
        .filter(|&i| is_word_token(a, &ta[i], &word_re))
        .collect();
    let words_b: Vec<usize> = (0..tb.len())
        .filter(|&i| is_word_token(b, &tb[i], &word_re))
        .collect();
    let l = lcs_len(&words_a, &words_b);
    let n = std::cmp::max(words_a.len(), words_b.len());
    let distance = if n == 0 { 0.0 } else { 1.0 - (l as f64) / (n as f64) };
    if distance > max_distance {
        return None;
    }
    let ops = diff_tokens(&ta, &tb);
    let mut del: Vec<(usize, usize)> = Vec::new();
    let mut ins: Vec<(usize, usize)> = Vec::new();
    for op in &ops {
        match op {
            (Op::Delete, i, _) => {
                let (s, e) = ta[*i];
                del.push((s, e));
            }
            (Op::Insert, _, j) => {
                let (s, e) = tb[*j];
                ins.push((s, e));
            }
            _ => {}
        }
    }
    Some((merge_ranges(del), merge_ranges(ins)))
}

pub fn parse_hunk_header(line: &str) -> HunkHeader {
    let mut h = HunkHeader::default();
    h.raw = line.to_string();
    let body = line.trim_start_matches("@@").trim_start();
    let mut it = body.split_whitespace();
    if let Some(m) = it.next() {
        let m = m.trim_start_matches('-');
        h.minus_start = m.split(',').next().and_then(|s| s.parse::<usize>().ok());
    }
    if let Some(p) = it.next() {
        let p = p.trim_start_matches('+');
        h.plus_start = p.split(',').next().and_then(|s| s.parse::<usize>().ok());
    }
    h
}

pub fn run(cfg: &Config, input: &str, color_only: bool) -> Vec<u8> {
    let mut p = Painter::new(cfg, color_only);
    let mut mode = Mode::Outside;
    for raw_line in input.split('\n') {
        let line = raw_line.strip_suffix('\r').unwrap_or(raw_line);
        match mode {
            Mode::Outside => {
                if line.starts_with("diff --git ")
                    || (line.starts_with("diff ") && !line.starts_with("diff --diff"))
                {
                    p.begin_section(line);
                    mode = Mode::FileHeader;
                    continue;
                }
                if line.starts_with("--- ") {
                    p.begin_unified(line);
                    mode = Mode::FileHeader;
                    continue;
                }
                if line.starts_with("Only in ") {
                    p.emit_pass_line(line);
                    continue;
                }
                if p.commit_re_match(line) {
                    p.emit_commit_line(line);
                    continue;
                }
                p.emit_pass_line(line);
            }
            Mode::FileHeader => {
                if line.starts_with("@@") {
                    p.finish_header();
                    p.begin_hunk(line);
                    mode = Mode::Hunk;
                    continue;
                }
                if line.starts_with("diff --git ")
                    || line.starts_with("diff ")
                    || line.starts_with("Only in ")
                    || p.commit_re_match(line)
                {
                    p.finish_header();
                    mode = Mode::Outside;
                    p.process(line);
                    continue;
                }
                p.header_line(line);
            }
            Mode::Hunk => {
                if line.starts_with("diff --git ")
                    || line.starts_with("diff ")
                    || line.starts_with("Only in ")
                    || p.commit_re_match(line)
                {
                    p.flush_hunk();
                    mode = Mode::Outside;
                    p.process(line);
                    continue;
                }
                if line.starts_with("@@") {
                    p.flush_hunk();
                    p.begin_hunk(line);
                    continue;
                }
                p.hunk_line(line);
            }
        }
    }
    p.finish();
    p.out
}
