    pub fn auto_bg(&self, name: &str) -> Option<Color> {
        let color = if minus_bg_style_names().contains(&name) {
            if self.true_color {
                Color::Rgb(0x3f, 0x00, 0x01)
            } else {
                Color::Ansi256(52)
            }
        } else if minus_emph_bg_style_names().contains(&name) {
            if self.true_color {
                Color::Rgb(0x90, 0x10, 0x11)
            } else {
                Color::Ansi256(124)
            }
