                Color::Rgb(0x00, 0x28, 0x00)
            } else {
                Color::Ansi256(22)
            }
        } else if plus_emph_bg_style_names().contains(&name) {
            if self.true_color {
                Color::Rgb(0x00, 0x60, 0x00)
            } else {
                Color::Ansi256(28)
            }
        } else {
            return None;
        };
        Some(self.light_variant(color))
    }

    /// Map a dark-mode auto color to its light-mode counterpart.
    pub fn light_variant(&self, c: Color) -> Color {
        if self.dark {
            return c;
        }
        match c {
            Color::Ansi256(52) => Color::Ansi256(224),
            Color::Ansi256(124) => Color::Ansi256(217),
            Color::Ansi256(22) => Color::Ansi256(194),
            Color::Ansi256(28) => Color::Ansi256(157),
            Color::Rgb(0x3f, 0x00, 0x01) => Color::Rgb(0xff, 0xe0, 0xe0),
