            Color::Rgb(0x00, 0x60, 0x00) => Color::Rgb(0xa0, 0xef, 0xa0),
            other => other,
        }
    }

    /// Resolve the `auto` foreground color for a style option.
    pub fn auto_fg(&self, name: &str) -> Option<Color> {
        match name {
            "line-numbers-minus-style" => Some(Color::Ansi256(88)),
            "line-numbers-plus-style" => Some(Color::Ansi256(28)),
            "line-numbers-zero-style" => Some(if self.true_color {
                Color::Rgb(0x44, 0x44, 0x44)
            } else {
                Color::Ansi256(238)
            }),
            "line-numbers-left-style" | "line-numbers-right-style" => Some(Color::Ansi(4)),
            _ => None,
        }
    }

