/// Parse a line-number format string like "{nm:^4}⋮" and render it.
pub fn format_line_number(fmt: &str, nm: Option<usize>, np: Option<usize>) -> String {
    let mut out = String::new();
    let chars: Vec<char> = fmt.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        if chars[i] == '{' {
            // find the matching '}'
            let mut j = i + 1;
            while j < chars.len() && chars[j] != '}' {
                j += 1;
            }
            if j < chars.len() {
                let spec: String = chars[i + 1..j].iter().collect();
                let (name, align, width) = parse_placeholder(&spec);
                let val = match name.as_str() {
                    "nm" => nm.map(|v| v.to_string()).unwrap_or_default(),
                    "np" => np.map(|v| v.to_string()).unwrap_or_default(),
                    "n" => nm.or(np).map(|v| v.to_string()).unwrap_or_default(),
                    _ => String::new(),
                };
                out.push_str(&pad_align(&val, align, width));
                i = j + 1;
                continue;
            }
        }
        out.push(chars[i]);
        i += 1;
    }
    out
}

fn parse_placeholder(spec: &str) -> (String, char, usize) {
    let mut name = String::new();
    let mut align = '^';
    let mut width = 0usize;
    let mut it = spec.chars();
    for c in it.by_ref() {
        if c == ':' {
            break;
        }
        name.push(c);
    }
    let rest: String = it.collect();
    let mut chars = rest.chars();
    if let Some(c) = chars.next() {
        if c == '^' || c == '<' || c == '>' {
            align = c;
            let w: String = chars.collect();
            width = w.parse::<usize>().unwrap_or(0);
        } else {
            let mut w = String::new();
            w.push(c);
            w.extend(chars);
            width = w.parse::<usize>().unwrap_or(0);
        }
    }
    (name, align, width)
}

pub fn pad_align(s: &str, align: char, width: usize) -> String {
    let len = crate::utils::display_width(s);
    if width <= len {
        return s.to_string();
    }
    let pad = width - len;
    match align {
        '<' => format!("{}{}", s, " ".repeat(pad)),
        '>' => format!("{}{}", " ".repeat(pad), s),
        _ => {
            let left = (pad + 1) / 2;
            let right = pad - left;
            format!("{}{}{}", " ".repeat(left), s, " ".repeat(right))
        }
    }
}
