    let mut map: std::collections::HashMap<String, String> = std::collections::HashMap::new();
    for (k, v) in default_values() {
        map.insert(k.to_string(), v);
    }
    // ---- git config
    let no_gitconfig = m.get_flag("no_gitconfig");
    let config_path = m.get_one::<String>("config").cloned().unwrap_or_default();
    let mut entries: Vec<crate::gitconfig::Entry> = Vec::new();
    if !no_gitconfig {
        if !config_path.is_empty() {
            if let Ok(text) = std::fs::read_to_string(&config_path) {
                let c = crate::gitconfig::GitConfig::parse(
                    &text,
                    std::path::Path::new(&config_path).parent(),
                );
                entries.extend(c.entries);
            }
        } else {
            // system, XDG, ~/.gitconfig, repo .git/config
            if let Ok(text) = std::fs::read_to_string("/etc/gitconfig") {
                let c = crate::gitconfig::GitConfig::parse(&text, Some(std::path::Path::new("/etc")));
                entries.extend(c.entries);
            }
            let xdg = std::env::var("XDG_CONFIG_HOME")
                .map(|v| format!("{}/git/config", v))
                .unwrap_or_else(|_| {
                    format!("{}/.config/git/config", std::env::var("HOME").unwrap_or_default())
                });
            if let Ok(text) = std::fs::read_to_string(&xdg) {
                let c = crate::gitconfig::GitConfig::parse(
                    &text,
                    std::path::Path::new(&xdg).parent().and_then(|p| p.parent()),
                );
                entries.extend(c.entries);
            }
            if let Ok(home) = std::env::var("GIT_CONFIG_GLOBAL") {
                if let Ok(text) = std::fs::read_to_string(&home) {
                    let c = crate::gitconfig::GitConfig::parse(
                        &text,
                        std::path::Path::new(&home).parent(),
                    );
                    entries.extend(c.entries);
                }
            } else if let Ok(home) = std::env::var("HOME") {
                let p = format!("{}/.gitconfig", home);
                if let Ok(text) = std::fs::read_to_string(&p) {
                    let c = crate::gitconfig::GitConfig::parse(
                        &text,
                        std::path::Path::new(&p).parent(),
                    );
                    entries.extend(c.entries);
                }
            }
            // repo-local config
            if let Some(gitdir) = crate::utils::find_git_dir() {
                let p = format!("{}/config", gitdir);
                if let Ok(text) = std::fs::read_to_string(&p) {
                    let c = crate::gitconfig::GitConfig::parse(
                        &text,
                        std::path::Path::new(&p).parent(),
                    );
                    entries.extend(c.entries);
                }
            }
        }
    }
    let cfgobj = crate::gitconfig::GitConfig { entries };
    // ---- features
    let mut feature_names: Vec<String> = Vec::new();
    let git_features: Vec<String> = cfgobj
        .get("delta", None, "features")
        .map(|v| v.split_whitespace().map(|s| s.to_string()).collect())
        .unwrap_or_default();
    let env_features = std::env::var("DELTA_FEATURES").unwrap_or_default();
    let (env_add, env_list): (bool, Vec<String>) = if let Some(rest) = env_features.strip_prefix('+')
    {
        (true, rest.split_whitespace().map(|s| s.to_string()).collect())
    } else {
        (false, env_features.split_whitespace().map(|s| s.to_string()).collect())
    };
    let cli_features: Vec<String> = m
        .get_one::<String>("features")
        .map(|v| v.split_whitespace().map(|s| s.to_string()).collect())
        .unwrap_or_default();
    if env_add {
        feature_names.extend(git_features.clone());
        feature_names.extend(env_list.clone());
        feature_names.extend(cli_features.clone());
    } else {
        // env replaces git config features
        if !env_list.is_empty() {
            feature_names.extend(env_list.clone());
            feature_names.extend(cli_features.clone());
        } else {
            feature_names.extend(git_features.clone());
            feature_names.extend(cli_features.clone());
        }
    }
    // apply [delta] section, then features (last wins), then CLI
    let mut applied: Vec<String> = Vec::new();
    for e in cfgobj.entries.iter() {
        if e.section == "delta" && e.subsection.is_none() {
            applied.push(e.key.clone());
            map.insert(e.key.clone(), e.value.clone());
        }
    }
    for f in &feature_names {
        for e in cfgobj.entries.iter() {
            if e.section == "delta" && e.subsection.as_deref() == Some(f.as_str()) {
                map.insert(e.key.clone(), e.value.clone());
            }
        }
    }
    // ---- CLI args
    for spec in crate::cli::ARGS {
        if spec.long == "config" {
            continue;
        }
        if spec.takes_value {
            if let Some(v) = m.get_one::<String>(spec.long.replace('-', "_").as_str()) {
                map.insert(spec.long.to_string(), v.clone());
            }
        } else if let Some(b) = m.get_one::<bool>(spec.long.replace('-', "_").as_str()) {
            map.insert(spec.long.to_string(), if *b { "true" } else { "false" }.to_string());
        }
    }
    // ---- color.diff.whitespace
    if map.get("whitespace-error-style").map(|s| s.as_str()) == Some("magenta reverse") {
        if let Some(v) = cfgobj.get("color", Some("diff"), "whitespace") {
            map.insert("whitespace-error-style".to_string(), v.to_string());
        }
    }
    // ---- terminal width / true color / dark-light
    let (_, _) = crate::utils::terminal_size();
    let (term_width, _) = crate::utils::terminal_size();
    let dark = detect_dark_light(&m, &cfgobj);
    let true_color = match m.get_one::<String>("true_color").map(|s| s.as_str()) {
        Some("always") => true,
        Some("never") => false,
        _ => match map.get("true-color").map(|s| s.as_str()) {
            Some("always") => true,
            Some("never") => false,
            _ => std::env::var("COLORTERM")
                .map(|v| v == "truecolor" || v == "24bit")
                .unwrap_or(false),
        },
    };
    let width = match m.get_one::<String>("width") {
        Some(w) => parse_width(w, term_width),
        None => {
            let mut w = term_width.unwrap_or(80);
            if let Some(v) = map.get("width") {
                if let Ok(n) = v.parse::<usize>() {
                    w = n;
                } else {
                    w = parse_width(v, term_width);
                }
            }
            w
        }
    };
    // syntax theme: BAT_THEME env, else default for dark/light
    if map.get("syntax-theme").map(|s| s.is_empty()).unwrap_or(true) {
        if let Ok(t) = std::env::var("BAT_THEME") {
            if !t.is_empty() {
                map.insert("syntax-theme".to_string(), t);
            }
        }
    }
    Config {
        map,
        dark,
        true_color,
        width: if width == 0 { 80 } else { width },
    }
}

