/// Walk up from the current directory looking for a `.git` entry.
pub fn find_git_dir() -> Option<String> {
    let mut dir = std::env::current_dir().ok()?;
    loop {
        let p = dir.join(".git");
        if p.exists() {
            return Some(dir.to_string_lossy().to_string());
        }
        if !dir.pop() {
            return None;
        }
    }
}
