/// Highlight one line, returning (start, end, token) spans covering it.
pub fn highlight(
    lang: &str,
    line: &str,
    max_len: usize,
    _theme: &ThemeColors,
) -> Vec<(usize, usize, Tok)> {
    let def = lang_def(lang);
    let chars: Vec<char> = line.chars().collect();
    let n = chars.len().min(max_len);
    let mut out: Vec<(usize, usize, Tok)> = Vec::new();
    let mut plain_start = 0usize;
    macro_rules! flush {
        ($end:expr) => {
            if plain_start < $end {
                out.push((plain_start, $end, Tok::Plain));
            }
            plain_start = $end;
        };
    }
    if def.plain || n == 0 {
        if !chars.is_empty() {
            out.push((0, chars.len(), Tok::Plain));
        }
        return out;
    }
    let mut i = 0usize;
    while i < n {
        let rest: String = chars[i..].iter().collect();
        let mut matched = false;
        for lc in &def.line_comment {
            if rest.starts_with(lc) {
                flush!(i);
                out.push((i, chars.len(), Tok::Comment));
                return out;
            }
        }
        if let Some((bs, be)) = def.block_comment {
            if rest.starts_with(bs) {
                flush!(i);
                let mut j = i + bs.chars().count();
                let mut end = chars.len();
                while j < chars.len() {
                    let r2: String = chars[j..].iter().collect();
                    if r2.starts_with(be) {
                        end = j + be.chars().count();
                        break;
                    }
                    j += 1;
                }
                out.push((i, end, Tok::Comment));
                i = end;
                plain_start = i;
                matched = true;
            }
        }
        if !matched {
            for d in &def.string_delims {
                if chars[i] == *d {
                    flush!(i);
                    let mut j = i + 1;
                    let mut end = chars.len();
                    let mut segs: Vec<(usize, usize, Tok)> = Vec::new();
                    let mut seg_start = i;
                    while j < chars.len() {
                        if chars[j] == '\\' {
                            j += 2;
                            continue;
                        }
                        if def.string_placeholder && chars[j] == '{' {
                            // placeholder {...}
                            if seg_start < j {
                                segs.push((seg_start, j, Tok::String));
                            }
                            let mut k = j + 1;
                            while k < chars.len() && chars[k] != '}' {
                                k += 1;
                            }
                            let e2 = (k + 1).min(chars.len());
                            segs.push((j, e2, Tok::Constant));
                            j = e2;
                            seg_start = j;
                            continue;
                        }
                        if chars[j] == *d {
                            end = j + 1;
                            break;
                        }
                        j += 1;
                    }
                    if seg_start < end {
                        segs.push((seg_start, end, Tok::String));
                    }
                    for s in segs {
                        out.push(s);
                    }
                    i = end;
                    plain_start = i;
                    matched = true;
                    break;
                }
            }
        }
        if !matched && (chars[i].is_alphabetic() || chars[i] == '_') {
            let mut j = i;
            while j < chars.len()
                && (chars[j].is_alphanumeric()
                    || chars[j] == '_'
                    || def.ident_extra.contains(chars[j]))
            {
                j += 1;
            }
            let word: String = chars[i..j].iter().collect();
            // macro: ident!
            let mut end = j;
            let mut is_macro = false;
            if def.macro_bang && j < chars.len() && chars[j] == '!' {
                end = j + 1;
                is_macro = true;
            }
            flush!(i);
            if is_macro {
                out.push((i, end, Tok::Plain));
            } else if def.decl_fn.contains(&word.as_str()) {
                out.push((i, j, Tok::Keyword));
                // the following identifier is a function name
                let mut k = j;
                while k < chars.len() && chars[k].is_whitespace() {
                    k += 1;
                }
                let mut m = k;
                while m < chars.len()
                    && (chars[m].is_alphanumeric() || chars[m] == '_' || def.ident_extra.contains(chars[m]))
                {
                    m += 1;
                }
                if m > k {
                    flush!(k);
                    out.push((k, m, Tok::Function));
                    i = m;
                    plain_start = m;
                    continue;
                }
            } else if def.decl_class.contains(&word.as_str()) {
                out.push((i, j, Tok::Keyword));
                let mut k = j;
                while k < chars.len() && chars[k].is_whitespace() {
                    k += 1;
                }
                let mut m = k;
                while m < chars.len()
                    && (chars[m].is_alphanumeric() || chars[m] == '_' || def.ident_extra.contains(chars[m]))
                {
                    m += 1;
                }
                if m > k {
                    flush!(k);
                    out.push((k, m, Tok::Class));
                    i = m;
                    plain_start = m;
                    continue;
                }
            } else if def.keywords.contains(&word.as_str()) {
                out.push((i, j, Tok::Keyword));
            } else if def.builtins.contains(&word.as_str()) {
                out.push((i, j, Tok::Builtin));
            } else if j < chars.len() && chars[j] == '(' && !def.builtins.is_empty() {
                out.push((i, j, Tok::Function));
            } else {
                out.push((i, j, Tok::Plain));
            }
            i = end;
            plain_start = i;
            matched = true;
        }
        if !matched && chars[i].is_ascii_digit() {
            let mut j = i;
            while j < chars.len()
                && (chars[j].is_alphanumeric() || chars[j] == '.' || chars[j] == '_')
            {
                j += 1;
            }
            flush!(i);
            out.push((i, j, Tok::Number));
            i = j;
            plain_start = i;
            matched = true;
        }
        if !matched && "+-*/%=<>!&|^~?:".contains(chars[i]) {
            flush!(i);
            out.push((i, i + 1, Tok::Operator));
            i += 1;
            plain_start = i;
            matched = true;
        }
        if !matched {
            i += 1;
        }
    }
    flush!(chars.len());
    out
}
