pub fn color_for(t: Tok, th: &ThemeColors, true_color: bool) -> Color {
    let (rgb, n) = match t {
        Tok::Plain => th.plain,
        Tok::Comment => th.comment,
        Tok::String => th.string,
        Tok::Number => th.number,
        Tok::Keyword => th.keyword,
        Tok::Function => th.function,
        Tok::Class => th.class,
        Tok::Operator => th.operator,
        Tok::Parameter => th.parameter,
        Tok::Constant => th.constant,
        Tok::Builtin => th.builtin,
    };
    if true_color {
        Color::Rgb(rgb.0, rgb.1, rgb.2)
    } else {
        Color::Ansi256(n)
    }
