/// Find the language for a file name.
pub fn language_for(name: &str, default_language: &str) -> String {
    let lower = name.to_lowercase();
    let fname = lower.rsplit('/').next().unwrap_or(&lower).to_string();
    for (lang, exts) in LANGUAGES.iter() {
        for e in exts.split(", ") {
            if e.is_empty() {
                continue;
            }
            let e = e.to_lowercase();
            if e.starts_with('.') {
                if fname == e || lower == e {
                    return lang.to_string();
                }
            } else if fname == e || fname.ends_with(&format!(".{}", e)) {
                return lang.to_string();
            }
        }
    }
    default_language.to_string()
}

