// ---------------------------------------------------------------------------
// side-by-side layout
// ---------------------------------------------------------------------------

impl<'a> Painter<'a> {
    /// Compute the painted spans (text, style) for a diff line's content.
    pub fn paint_spans(&self, l: &PendingLine, emph_ranges: &[(usize, usize)]) -> Vec<(String, Style)> {
        let base_name = match l.kind {
            Kind::Minus => "minus-style",
            Kind::Plus => "plus-style",
            _ => "zero-style",
        };
        let emph_name = match l.kind {
            Kind::Minus => "minus-emph-style",
            _ => "plus-emph-style",
        };
        let base = self.cfg.resolved_style(base_name);
        if base.raw {
            return vec![(l.content.clone(), base.clone())];
        }
        let emph_style = self.cfg.resolved_style(emph_name);
        let ws_style = self.cfg.resolved_style("whitespace-error-style");
        let lang = self.current_language();
        let theme_name = {
            let t = self.cfg.get_or("syntax-theme", "");
            if t.is_empty() {
                if self.cfg.dark {
                    crate::config::DEFAULT_SYNTAX_THEME_DARK
                } else {
                    crate::config::DEFAULT_SYNTAX_THEME_LIGHT
                }
            } else {
                Box::leak(t.to_string().into_boxed_str())
            }
        };
        let theme = crate::syntax::theme_colors(theme_name);
        let max_syntax = self.cfg.get_int("max-syntax-highlighting-length", 400);
        let syn = match &theme {
            Some(t) => crate::syntax::highlight(&lang, &l.content, max_syntax, t),
            None => vec![],
        };
        let chars: Vec<char> = l.content.chars().collect();
        let n = chars.len();
        let mut styles: Vec<Style> = vec![base.clone(); n];
        for (s, e, tok) in &syn {
            for i in (*s).min(n)..(*e).min(n) {
                if styles[i].fg == Some(Color::Syntax) {
                    styles[i].fg =
                        Some(crate::syntax::color_for(*tok, theme.as_ref().unwrap(), self.cfg.true_color));
                }
            }
        }
        for (s, e) in emph_ranges {
            for i in (*s).min(n)..(*e).min(n) {
                let mut st = emph_style.clone();
                if st.fg == Some(Color::Syntax) {
                    st.fg = styles[i].fg.clone();
                }
                styles[i] = st;
            }
        }
        if l.kind == Kind::Plus {
            let mut i = n;
            while i > 0 && (chars[i - 1] == ' ' || chars[i - 1] == '\t') {
                i -= 1;
            }
            for j in i..n {
                let mut st = ws_style.clone();
                if st.fg == Some(Color::Syntax) {
                    st.fg = styles[j].fg.clone();
                }
                styles[j] = st;
            }
        }
        let mut out: Vec<(String, Style)> = Vec::new();
        let mut i = 0;
        while i < n {
            let s = styles[i].clone();
            let mut j = i + 1;
            while j < n && styles[j] == s {
                j += 1;
            }
            out.push((chars[i..j].iter().collect(), s));
            i = j;
        }
        out
    }

    fn num_col_width(&self) -> usize {
        let left_fmt = self.cfg.get_or("line-numbers-left-format", "{nm:^4}\u{22ee}");
        let (num, _div) = split_format(&left_fmt);
        let w = placeholder_width(&num);
        w + 2
    }

    fn content_width(&self) -> usize {
        let nw = self.num_col_width();
        (self.cfg.width.saturating_sub(2 * nw)) / 2
    }
}

pub fn placeholder_width(spec: &str) -> usize {
    match parse_placeholder(spec) {
        (_, _, w) => w,
    }
}
