/// Wrap/truncate a painted span list into column chunks.
fn wrap_spans(
    spans: &[(String, Style)],
    w: usize,
    max_wraps: usize,
    right_percent: f64,
) -> Vec<Vec<(String, Style)>> {
    // flatten to per-char (char, style)
    let mut chars: Vec<(char, Style)> = Vec::new();
    for (t, s) in spans {
        for c in t.chars() {
            chars.push((c, s.clone()));
        }
    }
    let total = chars.len();
    let mut lines: Vec<Vec<(char, Style)>> = Vec::new();
    let mut pos = 0usize;
    let mut first = true;
    loop {
        if pos >= total {
            break;
        }
        let remaining = total - pos;
        let is_last_allowed = lines.len() >= max_wraps;
        let cap = if first {
            if remaining <= w { w } else { w - 1 }
        } else if is_last_allowed {
            if remaining <= w { w } else { w - 1 }
        } else if remaining <= w {
            w
        } else {
            w - 1
        };
        let take = cap.min(remaining);
        lines.push(chars[pos..pos + take].to_vec());
        pos += take;
        first = false;
        if lines.len() > max_wraps {
            break;
        }
    }
    if lines.is_empty() {
        lines.push(Vec::new());
    }
    // decide alignment of the last line
    let n = lines.len();
    let mut out: Vec<Vec<(String, Style)>> = Vec::new();
    for (i, line) in lines.iter().enumerate() {
        let is_last = i == n - 1;
        let truncated = is_last && pos < total;
        let mut s: Vec<(String, Style)> = Vec::new();
        if is_last && !truncated && !line.is_empty() {
            let frac = line.len() as f64 / w as f64 * 100.0;
            if frac < right_percent && n > 1 {
                // right-aligned: fill + prefix symbol + content
                s.push((String::new(), Style::default()));
            }
        }
        let mut prev: Option<Style> = None;
        for (c, st) in line {
            match &mut s.last_mut() {
                Some((t, ls)) if Some(ls) == prev.as_ref() => {
                    t.push(*c);
                }
                _ => {
                    s.push((c.to_string(), st.clone()));
                    prev = Some(st.clone());
                }
            }
        }
        out.push(s);
    }
    out
}
