/// Emit the side-by-side layout for one input line.
impl<'a> Painter<'a> {
    fn emit_sbs(&mut self, l: &PendingLine, emph: &[(usize, usize)]) {
        let nw = self.num_col_width();
        let w = self.content_width();
        let max_wraps = self.cfg.get_int("wrap-max-lines", 2);
        let right_percent = self.cfg.get_float("wrap-right-percent", 37.0);
        let left_symbol = self.cfg.get_or("wrap-left-symbol", "\\u{21b5}");
        let right_symbol = self.cfg.get_or("wrap-right-symbol", "\\u{21b4}");
        let prefix_symbol = self.cfg.get_or("wrap-right-prefix-symbol", "\\u{2026}");
        let hint = self.cfg.resolved_style("inline-hint-style");
        let base = self.cfg.resolved_style(match l.kind {
            Kind::Minus => "minus-style",
            Kind::Plus => "plus-style",
            _ => "zero-style",
        });
        let spans = self.paint_spans(l, emph);
        let left_chunks = if l.kind == Kind::Plus {
            vec![]
        } else {
            wrap_spans(&spans, w, max_wraps, right_percent)
        };
        let right_chunks = if l.kind == Kind::Minus {
            vec![]
        } else {
            wrap_spans(&spans, w, max_wraps, right_percent)
        };
        let nlines = std::cmp::max(std::cmp::max(left_chunks.len(), right_chunks.len()), 1);
        let left_align: Vec<bool> = left_chunks
            .iter()
            .enumerate()
            .map(|(i, c)| {
                let is_last = i == left_chunks.len() - 1;
                let truncated = is_last && left_chunks.len() > max_wraps + 1;
                let _ = truncated;
                is_last
                    && left_chunks.len() > 1
                    && !c.is_empty()
                    && crate::utils::display_width(
                        &c.iter().map(|(t, _)| t.clone()).collect::<String>(),
                    ) as f64
                        / w as f64
                        * 100.0
                        < right_percent
            })
            .collect();
        let right_align: Vec<bool> = right_chunks
            .iter()
            .enumerate()
            .map(|(i, c)| {
                let is_last = i == right_chunks.len() - 1;
                is_last
                    && right_chunks.len() > 1
                    && !c.is_empty()
                    && crate::utils::display_width(
                        &c.iter().map(|(t, _)| t.clone()).collect::<String>(),
                    ) as f64
                        / w as f64
                        * 100.0
                        < right_percent
            })
            .collect();
        for k in 0..nlines {
            // line-number columns
            self.emit_sbs_num_col(true, l, k == 0, nw);
            // left content
            if l.kind == Kind::Plus {
                self.write_str(&" ".repeat(w));
            } else if let Some(chunk) = left_chunks.get(k) {
                self.emit_sbs_chunk(
                    chunk,
                    w,
                    base.clone(),
                    if k + 1 < left_chunks.len() {
                        Some(if *right_align.get(k + 1).unwrap_or(&false) {
                            right_symbol.clone()
                        } else {
                            left_symbol.clone()
                        })
                    } else {
                        None
                    },
                    &hint,
                    *left_align.get(k).unwrap_or(&false),
                    &prefix_symbol,
                    k + 1 >= left_chunks.len() && left_chunks.len() > max_wraps + 1,
                );
            }
            // right line-number column
            self.emit_sbs_num_col(false, l, k == 0, nw);
            // right content
            if l.kind != Kind::Minus {
                if let Some(chunk) = right_chunks.get(k) {
                    self.emit_sbs_chunk(
                        chunk,
                        w,
                        base.clone(),
                        if k + 1 < right_chunks.len() {
                            Some(if *right_align.get(k + 1).unwrap_or(&false) {
                                right_symbol.clone()
                            } else {
                                left_symbol.clone()
                            })
                        } else {
                            None
                        },
                        &hint,
                        *right_align.get(k).unwrap_or(&false),
                        &prefix_symbol,
                        k + 1 >= right_chunks.len() && right_chunks.len() > max_wraps + 1,
                    );
                }
            }
            self.write_str("\\n");
        }
    }

    #[allow(clippy::too_many_arguments)]
    fn emit_sbs_chunk(
        &mut self,
        chunk: &[(String, Style)],
        w: usize,
        base: Style,
        symbol: Option<String>,
        hint: &Style,
        right_align: bool,
        prefix_symbol: &str,
        truncated: bool,
    ) {
        let mut st = AnsiState::default();
        let content_len: usize = chunk
            .iter()
            .map(|(t, _)| crate::utils::display_width(t))
            .sum();
        if right_align && !chunk.is_empty() {
            // fill, then the prefix symbol, then the content
            let fill = w.saturating_sub(content_len + 1);
            if let Some(bg) = &base.bg {
                if bg != &Color::Normal {
                    let f = AnsiState {
                        attrs: 0,
                        fg: None,
                        bg: Some(self.resolve_color(bg)),
                    };
                    let t = AnsiState::default().transition(&f);
                    self.write_str(&t);
                    self.write_str(&" ".repeat(fill));
                    self.write_str("\\x1b[0m");
                    st = AnsiState::default();
                } else {
                    self.write_str(&" ".repeat(fill));
                }
            } else {
                self.write_str(&" ".repeat(fill));
            }
            let ht = AnsiState::default().transition(&AnsiState {
                attrs: hint.attrs,
                fg: hint.fg.clone().map(|c| self.resolve_color(&c)),
                bg: None,
            });
            self.write_str(&ht);
            self.write_str(prefix_symbol);
            self.write_str("\\x1b[0m");
            st = AnsiState::default();
        }
        for (text, style) in chunk {
            let target = AnsiState {
                attrs: style.attrs & !crate::style::ATTR_OMIT,
                fg: style.fg.clone().map(|c| self.resolve_color(&c)),
                bg: style.bg.clone().map(|c| self.resolve_color(&c)),
            };
            let t = st.transition(&target);
            if !t.is_empty() {
                self.write_str(&t);
            }
            self.write_str(text);
            st = target;
        }
        if truncated {
            let t = st.transition(&AnsiState {
                attrs: crate::style::ATTR_REVERSE,
                fg: None,
                bg: None,
            });
            self.write_str(&t);
            self.write_str("\\u{2192}");
            self.write_str("\\x1b[0m");
            return;
        }
        if let Some(sym) = symbol {
            let t = st.transition(&AnsiState {
                attrs: hint.attrs,
                fg: hint.fg.clone().map(|c| self.resolve_color(&c)),
                bg: None,
            });
            self.write_str(&t);
            self.write_str(&sym);
            self.write_str("\\x1b[0m");
            st = AnsiState::default();
        }
        // fill the rest of the column
        let used = content_len + if symbol.is_some() || truncated { 1 } else { 0 };
        let fill = w.saturating_sub(used);
        if fill > 0 {
            if let Some(bg) = &base.bg {
                if bg != &Color::Normal {
                    let f = AnsiState {
                        attrs: 0,
                        fg: None,
                        bg: Some(self.resolve_color(bg)),
                    };
                    let t = st.transition(&f);
                    if !t.is_empty() {
                        self.write_str(&t);
                    }
                    self.write_str(&" ".repeat(fill));
                    self.write_str("\\x1b[0m");
                    return;
                }
            }
            self.write_str(&" ".repeat(fill));
        } else {
            let t = st.transition(&AnsiState::default());
            self.write_str(&t);
        }
    }

    fn emit_sbs_num_col(&mut self, is_left: bool, l: &PendingLine, first: bool, nw: usize) {
        let fmt = if is_left {
            self.cfg.get_or("line-numbers-left-format", "{nm:^4}\\u{22ee}")
        } else {
            self.cfg.get_or("line-numbers-right-format", "{np:^4}\\u{2502}")
        };
        let col_style = if is_left {
            self.cfg.resolved_style("line-numbers-left-style")
        } else {
            self.cfg.resolved_style("line-numbers-right-style")
        };
        let num_style = if is_left {
            match l.kind {
                Kind::Zero => self.cfg.resolved_style("line-numbers-zero-style"),
                _ => self.cfg.resolved_style("line-numbers-minus-style"),
            }
        } else {
            match l.kind {
                Kind::Zero => self.cfg.resolved_style("line-numbers-zero-style"),
                _ => self.cfg.resolved_style("line-numbers-plus-style"),
            }
        };
        let (num_spec, _div) = split_format(&fmt);
        let nw_ = nw - 2;
        let val = if !first {
            String::new()
        } else {
            match (is_left, l.kind) {
                (true, Kind::Plus) => String::new(),
                (false, Kind::Minus) => String::new(),
                (true, _) => l.minus_ln.map(|v| v.to_string()).unwrap_or_default(),
                (false, _) => l.plus_ln.map(|v| v.to_string()).unwrap_or_default(),
            }
        };
        let text = pad_align(&val, parse_placeholder(&num_spec).1, nw_);
        let col = AnsiState {
            attrs: col_style.attrs & !crate::style::ATTR_OMIT,
            fg: col_style.fg.clone().map(|c| self.resolve_color(&c)),
            bg: col_style.bg.clone().map(|c| self.resolve_color(&c)),
        };
        let num = AnsiState {
            attrs: num_style.attrs & !crate::style::ATTR_OMIT,
            fg: num_style.fg.clone().map(|c| self.resolve_color(&c)),
            bg: num_style.bg.clone().map(|c| self.resolve_color(&c)),
        };
        let mut st = AnsiState::default();
        let t = st.transition(&col);
        self.write_str(&t);
        self.write_str("\\u{2502}");
        st = col.clone();
        let t = st.transition(&num);
        self.write_str(&t);
        self.write_str(&text);
        st = num;
        let t = st.transition(&col);
        self.write_str(&t);
        self.write_str("\\u{2502}");
        if !is_left {
            self.write_str("\\x1b[0m");
        }
    }
}
