fn wrap_spans(
    spans: &[(String, Style)],
    w: usize,
    max_wraps: usize,
    right_percent: f64,
) -> Vec<Vec<(String, Style)>> {
    let mut chars: Vec<(char, Style)> = Vec::new();
    for (t, s) in spans {
        for c in t.chars() {
            chars.push((c, s.clone()));
        }
    }
    let total = chars.len();
    let mut lines: Vec<Vec<(char, Style)>> = Vec::new();
    let mut pos = 0usize;
    let mut truncated = false;
    if total == 0 {
        lines.push(Vec::new());
    }
    while pos < total {
        let remaining = total - pos;
        let last_allowed = lines.len() >= max_wraps;
        let cap = if remaining <= w {
            w
        } else {
            w - 1
        };
        let take = cap.min(remaining);
        lines.push(chars[pos..pos + take].to_vec());
        pos += take;
        if last_allowed && pos < total {
            truncated = true;
            break;
        }
        if lines.len() > max_wraps + 1 {
            break;
        }
    }
    let n = lines.len();
    let mut out: Vec<Vec<(String, Style)>> = Vec::new();
    for (i, line) in lines.iter().enumerate() {
        let is_last = i == n - 1;
        let mut right_align = false;
        if is_last && !truncated && n > 1 && !line.is_empty() {
            let frac = line.len() as f64 / w as f64 * 100.0;
            if frac < right_percent {
                right_align = true;
            }
        }
        let mut s: Vec<(String, Style)> = Vec::new();
        if right_align {
            s.push(("\\u{2026}".to_string(), Style::default()));
        }
        for (c, st) in line {
            match s.last_mut() {
                Some((t, ls)) if *ls == *st => t.push(*c),
                _ => s.push((c.to_string(), st.clone())),
            }
        }
        out.push(s);
    }
    out
